function SourceContainer(source, tostr, start_line0, start_column0) {

    var sc = this;

    sc.source = source;
    sc.tostr = tostr;
    sc.start_line0 = start_line0;
    sc.start_column0 = start_column0;
}

SourceContainer.prototype.toString = function () {

    var sc = this;

    if (sc.is_repl()) {
        return '<REPL>';
    } else if (sc.is_html()) {
        return '<HTML>';
    } else {
        return sc.tostr;
    }
};

SourceContainer.prototype.is_repl = function () {

    var sc = this;

    return sc.tostr === false;
}

SourceContainer.prototype.is_html = function () {

    var sc = this;

    return sc.tostr === null;
}

SourceContainer.prototype.toString = function () {

    var sc = this;

    return sc.tostr;
};

function SourceContainerInternalFile(source, tostr, start_line0, start_column0, stamp) {

    var sc = this;

    sc.source = source;
    sc.tostr = tostr;
    sc.start_line0 = start_line0;
    sc.start_column0 = start_column0;
    sc.stamp = stamp;
}

SourceContainerInternalFile.prototype.is_repl = function () {
    return false;
}

SourceContainerInternalFile.prototype.is_html = function () {
    return false;
}

SourceContainerInternalFile.prototype.toString = function () {

    var sc = this;

    return sc.tostr;
};


