LangPy.prototype.initRunTimeState = function (reboot) {

    var lang = this;

    //console.log('LangPy.initRunTimeState reboot='+reboot);

    if (!lang.rt.rte || reboot) {
        lang.rt.rte = lang.makeFreshRunTimeState();
    }
};

LangPy.prototype.makeFreshRunTimeState = function() {
  var lang = this;

  // default 'trace' option to false
  var options = { trace: false, safe_for_space: false };

  // Init rte
  var rte = pyinterp.fresh_rte(options, lang.vm);

  return rte;
}

LangPy.prototype.getCompletionNames = function () {
  var lang = this;

  if (!lang.cached_completion_names) {
    var dummy_rte = lang.makeFreshRunTimeState();

    lang.cached_completion_names = pyinterp.get_globally_available_names(dummy_rte);
  }

  return lang.cached_completion_names;

}

