function drawing_setScreenMode(rte, width, height, scale) {

    var pw = rte.vm.ui.pw;

    if (width !== void 0) {

        //TODO: add translation?
        if (typeof width !== 'number' ||
            Math.floor(width) !== width ||
            width < 1 ||
            width > pw.max_width) {
            throw 'width parameter of setScreenMode must be a positive integer no greater than ' + pw.max_width;
        }

        if (height === void 0) {
            height = Math.min(width, pw.max_height);
        } else {
            if (typeof height !== 'number' ||
                Math.floor(height) !== height ||
                height < 1 ||
                height > pw.max_height) {
                throw 'height parameter of setScreenMode must be a positive integer no greater than ' + pw.max_height;
            }
        }

        if (scale === void 0) {
            scale = Math.max(1, Math.min(20,
                                         Math.floor(360 / width),
                                         Math.floor(240 / height)));
        } else {
            if (typeof scale !== 'number' ||
                Math.floor(scale) !== scale ||
                scale < 1 ||
                scale > 1000) {
                throw 'scale parameter of setScreenMode must be a positive integer no greater than 1000';
            }
        }

        if (width !== pw.width || height !== pw.height || scale !== pw.scale) {
            pw.setScreenMode(width, height, scale);
        } else {
            pw.clearScreen();
        }
    }

    pw.prepareToShow();
}

