function runtime_string_hash(string) {
  // simple hash from https://stackoverflow.com/questions/7616461/generate-a-hash-from-string-in-javascript
  // Convert to 32bit positive integer
  var hash = 3522646, i, chr;
  if (string.length === 0) return hash;
  for (i = 0; i < string.length; i++) {
    chr = string.charCodeAt(i);
    hash = ((hash << 5) - hash) + chr;
    hash |= 0; // Convert to 32bit integer
  }

  var signed = new Int32Array(1);
  var bytes = new Uint32Array(signed.buffer);

  signed[0] = hash

  return bytes[0]
}

function runtime_float_hash(number) {
  // hash function for number which returns the number itself for integral numbers
  if (Number.isInteger(number)) {
    return number
  }

  var view = new Float64Array(1);
  var bytes = new Int32Array(view.buffer);

  view[0] = number;

  // return a 32-bit integer
  return bytes[1] ^ bytes[0]
}

