// Global state.
//
// The CodeBoot class has a single instance, stored in CodeBoot.prototype.cb .

function CodeBoot() {

    var cb = this;

    cb.vms = {};
    cb.vmsCreated = 0;
    cb.vmCount = 0;

    cb.cmds = null;

    cb.seqnum = 0;

    cb.setupMouseState();
    cb.setupKeyboardState();
    cb.setupKeyboardHandling();

    cb.confirmLeavingOnClose = false;

    document.addEventListener('DOMContentLoaded', function (event) {
        cb.DOMContentLoaded();
    });
}

CodeBoot.prototype.DOMContentLoaded = function () {

    var cb = this;

    // Delay codeBoot initialization until other components are initialized.

    if (typeof Reveal !== 'undefined') {

        console.log('Reveal js detected...');

        // Only start initializing codeBoot once reveal.js is ready

        Reveal.on('ready', function (event) {
            Reveal.configure({ minScale: 1, maxScale: 1 });
            cb.init();
        });

        // refresh CodeMirror each time we change page see
        // https://github.com/codemirror/CodeMirror/issues/61

        Reveal.on('slidechanged', function (event) {
            event.currentSlide.querySelectorAll('.CodeMirror')
                .forEach(function (elem) {
                    elem.CodeMirror.refresh();
                });
        });
    }
    else {
        cb.init();
    }
};

CodeBoot.prototype.setupMouseState = function () {

    var cb = this;

    cb.mouse = {
        x: 0,
        y: 0,
        button: 0,
        alt: false,
        ctrl: false,
        meta: false,
        shift: false
    };
};

CodeBoot.prototype.setupKeyboardState = function () {

    var cb = this;

    cb.keyboard = {
        altLeft: false,
        altRight: false,
        ctrlLeft: false,
        ctrlRight: false,
        metaLeft: false,
        metaRight: false,
        shiftLeft: false,
        shiftRight: false
    };
};

CodeBoot.prototype.init = function () {

    var cb = this;

    cb.initStartHook();

    var scope = document.body;

    cb.extractCommandsFromLocation();

    cb.setupBeforeunloadHandling();

    cb.setupMouseMotionTracking(scope);

    cb.setupFocusTracking();

    cb.rewrite_event_handlers(null, scope);

    cb.setupAllVM(scope);

//    if (!CodeBoot.prototype.hasTouchInterface()) {
//        $(function () {
//            $('[data-toggle="tooltip"]').tooltip();
//        });
//    }

    /*
        window.onbeforeunload = function () {
            if (cb.saveInProgress) {
                cb.saveInProgress = false;
                return undefined;
            }
            if (!cb.priviledged) {
                return 'Your codeBoot session will be lost.'
            } else {
                return undefined;
            }
        };
    
        if (!CodeMirror.commands.save) {
            CodeMirror.commands.save = function (cm) {
                if (cm.save) cm.save(cm);
            };
        }
    */
    //    cb.handle_query();

    cb.initEndHook();
};

CodeBoot.prototype.initStartHook = function () {
};

CodeBoot.prototype.initEndHook = function () {
};

CodeBoot.prototype.commandsQueryParam = 'init';

CodeBoot.prototype.extractCommands = function (uri) {

    var cb = this;

    var queryString = (new URL(uri)).search;
    var params = Object.fromEntries((new URLSearchParams(queryString)).entries());
    var commandsParam = params[cb.commandsQueryParam];

    if (!commandsParam) return [true]; // empty commands

    var parts = commandsParam.split('.');
    var cmds = parts.slice(1);
    var signature = parts[0];

    if (cb.ignoreSignatures) {
        cmds.unshift(true);
    } else if (signature === '') {
        cmds.unshift(false);
    } else {
        cmds.unshift(cb.verifyString(CodeBoot.prototype.cb.commandsToSign(cmds).join('.'), signature));
    }

    return cmds;
};

CodeBoot.prototype.extractAppParams = function(uri) {
    var cb = this;

    var queryString = (new URL(uri)).search;
    var params = Object.fromEntries((new URLSearchParams(queryString)).entries());

    // The commandsQueryParam (usually 'init') is reserved for initializing the VM, other params can be used
    // by a codeboot app (ex: a Python program may access them)
    delete params[cb.commandsQueryParam];

    return params;
}

CodeBoot.prototype.extractAppParamsFromLocation = function() {
    var cb = this;
    return cb.extractAppParams(window.location.href);
}

// * DEPRECATED?
// OM: I didn't want to remove it due to its ramification in init(), but it feels like it should be removed
CodeBoot.prototype.extractCommandsFromLocation = function () {

    var cb = this;

    cb.cmds = cb.extractCommands(window.location.href);
};

CodeBoot.prototype.getCommandsParams = function() {
    // TODO: should we save the params at initialisation?
    var cb = this;

    var cmds = cb.extractCommands(window.location.href);

    function clearKeyword(name) {
        // Remove ~~
        return name.slice(2);
    }

    function splitParam(s) {
        let index = s.indexOf('=');
        if (index === -1) {
            return [clearKeyword(s), true];
        } else {
            return [clearKeyword(s.slice(0, index)), s.slice(index + 1)];
        }
    }

    const toObj = (list) => {
        let obj = {};
        list.forEach(pair => { obj[pair[0]] = pair[1]; });
        return obj;
    }

    return toObj(cmds.filter((s) => typeof s === "string" && s.startsWith("~~")).map(splitParam));
}

CodeBoot.prototype.isIsolatedLocation = function () {

    var cb = this;

    var location = window.location;
    var protocol = location.protocol;
    var host = location.host;

    return protocol !== 'https:' || cb.isIsolatedSubdomain(host);
};

CodeBoot.prototype.isIsolatedSubdomain = function (host) {

    var cb = this;

    for (var i = 0; i < cb.isolatedSubdomains.length; i++) {
        var subdomain = cb.isolatedSubdomains[i];
        if (subdomain.length > 0 && host.indexOf(subdomain) === 0) return true;
    }

    return false;
};

CodeBoot.prototype.getCodeBootLocation = function (isolated) {

    var cb = this;

    var location = window.location;
    var protocol = location.protocol;
    var host = location.host;
    var pathname = location.pathname;

    var subdomain = '';

CodeBoot.prototype.isolatedDomain = '$HOME_DOMAIN';

    if (!(protocol === 'http:' || protocol === 'https:') ||
        host.split(':')[0] === 'localhost' ||
        cb.useHomeDomainForIsolated) {
        protocol = 'https:';
        host = cb.homeDomain;
        if (cb.isolatedSubdomains.length >= 1) {
            host = cb.isolatedSubdomains[0] + host;
        }
        pathname = '/' + cb.version + '/';
    } else if (isolated &&
               !cb.isIsolatedLocation() &&
               cb.isolatedSubdomains.length >= 1) {
        var parts = host.split('.');
        if (parts.length > 2) parts = parts.slice(-2);
        host = cb.isolatedSubdomains[0] + parts.join('.');
    }

    return 'https://' + host + pathname;
};

CodeBoot.prototype.setupBeforeunloadHandling = function () {

    var cb = this;

    window.addEventListener('beforeunload', function (event) {
        cb.saveAllVM();
        if (cb.confirmLeavingOnClose) {
            event.preventDefault();
        }
    });
};

CodeBoot.prototype.saveAllVM = function () {

    var cb = this;

    for (var id in cb.vms) {
        var vm = cb.vms[id];
        vm.saveSession();
    }
};

CodeBoot.prototype.setupMouseMotionTracking = function (elem) {

    var cb = this;

    function move(event) {
        cb.trackMouseMove(event);
    };

    elem.addEventListener('pointermove', move);
};

CodeBoot.prototype.setupFocusTracking = function () {

    var cb = this;

    //    document.addEventListener('focus', function () {
    //        console.log('focused:')
    //        console.log(document.activeElement)
    //    }, true);
};

CodeBoot.prototype.setupKeyboardHandling = function () {

    var cb = this;

    function keydown(event) {
        key(event, true);
    }

    function keyup(event) {
        key(event, false);
    }

    function key(event, down) {
        var code = event.code;
        if (code === 'AltLeft') {
            cb.keyboard.altLeft = down;
        } else if (code === 'AltRight') {
            cb.keyboard.altRight = down;
        } else if (code === 'ControlLeft') {
            cb.keyboard.ctrlLeft = down;
        } else if (code === 'ControlRight') {
            cb.keyboard.ctrlRight = down;
        } else if (code === 'MetaLeft' || code === 'OSLeft') {
            cb.keyboard.metaLeft = down;
        } else if (code === 'MetaRight' || code === 'OSRight') {
            cb.keyboard.metaRight = down;
        } else if (code === 'ShiftLeft') {
            cb.keyboard.shiftLeft = down;
        } else if (code === 'ShiftRight') {
            cb.keyboard.shiftRight = down;
        }
    }

    document.addEventListener('keydown', keydown);
    document.addEventListener('keyup', keyup);
};

CodeBoot.prototype.setupMouseHandling = function (elem, getWindowObj) {

    var cb = this;

    function down(event) {
        var b = event.buttons;
        cb.trackMouseDown(event, b > 1 ? 2 : b);
    }

    function up(event) {
        cb.trackMouseUp(event);
    }

    function move(event) {
        cb.trackMouseMove(event);
    }

    function contextmenu(event) {
        cb.preventContextMenu(event);
    }

    function screenshot(event) {
        getWindowObj().screenshot(event);
    }

    elem.addEventListener('contextmenu', contextmenu);

    elem.addEventListener('pointerdown', down);

    elem.addEventListener('pointerup', up);

    elem.addEventListener('pointermove', move);

    elem.addEventListener('dblclick', screenshot);

    //    elem.addEventListener('dragstart', function (event) {
    //        var dt = event.dataTransfer;
    //        dt.effectAllowed = 'copyMove';
    //        dt.setData('text/html', '<img src="' + getWindowObj().toDataURL() + '"/>');
    //    });
    //
    //    elem.setAttribute('draggable', 'true');
};

CodeBoot.prototype.trackMouseMove = function (event) {

    var cb = this;

    cb.mouse.x = event.pageX;
    cb.mouse.y = event.pageY;
};

CodeBoot.prototype.trackMouseUp = function (event) {

    var cb = this;

    cb.mouse.button = 0;
    cb.trackMouseMove(event);
};

CodeBoot.prototype.trackMouseDown = function (event, button) {

    var cb = this;

    cb.mouse.button = button;
    cb.mouse.alt = event.altKey;
    cb.mouse.ctrl = event.ctrlKey;
    cb.mouse.meta = event.metaKey;
    cb.mouse.shift = event.shiftKey;
    cb.trackMouseMove(event);
};

CodeBoot.prototype.preventContextMenu = function (event) {

    var cb = this;

    if (event.buttons & 2) {
        // secondary button was probably pressed
        cb.trackMouseDown(event, 2);
    }

    event.preventDefault(); // don't show context menu
};

CodeBoot.prototype.collectScripts = function (elem, script_type, cont) {

    var cb = this;

    var nb_scripts = 0;
    var source = '';
    var script_elems = elem.querySelectorAll('script');
    var index = 0;

    function loop() {
        if (index < script_elems.length) {
            var script = script_elems[index++];
            if (script.getAttribute('type') !== script_type) {
                loop();
            } else if (script.hasAttribute('src')) {
                cb.ajax(script.getAttribute('src'),
                    null,
                    10000, // timeout = 10 seconds
                    function (text) {
                        nb_scripts++;
                        source += text;
                        loop();
                    },
                    function (reason, status) {
                        loop();
                    });
            } else {
                nb_scripts++;
                source += script.innerText + '\n';
                loop();
            }
        } else if (nb_scripts === 0) {
            cont(null);
        } else {
            cont(source);
        }
    }

    loop();
};

CodeBoot.prototype.ajax = function (url, data, timeout, success, fail) {

    var cb = this;
    var xhr = new XMLHttpRequest();

    xhr.timeout = timeout;

    xhr.onreadystatechange = function () {

        if (xhr.readyState === 4) {
            if (xhr.status == 200) {
                success(xhr.responseText);
            } else {
                fail('error', xhr.status);
            }
        }
    };

    xhr.ontimeout = function () {
        fail('timeout', 0);
    };

    if (data === null) {
        xhr.open('GET', url, true);
    } else {
        xhr.open('POST', url, true);
        xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
    }

    xhr.send(data);

    return xhr;
};

CodeBoot.prototype.fetch_as_img = function (url, data, timeout, success, fail) {

    var cb = this;
    var img = document.createElement('img');

    var timerId = null;

    function cancelTimer() {
        if (timerId) {
            timerId = null;
            clearTimeout(timerId);
        }
    }

    timerId = setTimeout(function () {
        if (timerId) {
            timerId = null;
            fail('timeout', 0);
        }
    }, timeout);

    var query = '';
    var q = url.indexOf('?');

    if (q >= 0) {
        query = url.slice(q + 1);
        url = url.slice(0, q);
    }

    url += '??seqnum=' + (cb.seqnum++);

    if (data !== null) {
        url += '&content=' + CodeBoot.prototype.bytesToBase64URL(CodeBoot.prototype.stringToUTF8(data));
    }

    if (query.length > 0) {
        url += '&' + query;
    }

    img.addEventListener('load', function () {
        var w = img.width;
        var h = img.height;
        var canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        var ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        var data = ctx.getImageData(0, 0, w, h).data;
        var padding = data[0];
        var nbytes = (data.length >> 2) * 3 - padding - 1;
        var bytes = new Uint8Array(nbytes);
        var i = 1;
        var j = 0;
        while (j < nbytes) {
            if ((i & 3) === 3) i++;
            bytes[j++] = data[i++];
        }
        cancelTimer();
        success(CodeBoot.prototype.UTF8ToString(bytes));
    });

    img.addEventListener('error', function () {
        cancelTimer();
        fail('error', 0);
    });

    img.setAttribute('crossOrigin', '');
    img.src = url;
};

CodeBoot.prototype.setupAllVM = function (elem) {

    var cb = this;

    function init(root) {
        if (!getCodeBootVM(root)) {
            var opts = { root: root };
            var cmds = cb.cmds;
            if (cmds) {
                cb.cmds = null;
                if (cmds[0] === true || cb.isIsolatedLocation()) {
                    opts.cmds = cmds.slice(1);
                }
            }
            new CodeBootVM(opts);
        }
    }

    function done() {
        elem.querySelectorAll('.cb-vm').forEach(init);
        elem.querySelectorAll('pre[data-cb]').forEach(init);
    }

    var langs = [];
    var index = 0;
    Lang.prototype.forEachRegisteredLang(function (lang) { langs.push(lang); });

    function loop() {
        if (index < langs.length) {
            var lang = langs[index++];
            var script_type = lang.prototype.getScriptType();
            cb.collectScripts(
                document,
                script_type,
                function (source) {
                    if (source !== null) {
                        var levels = lang.prototype.getLevels();
                        var exts = lang.prototype.getExts();
                        var cmds = [CodeBoot.prototype.fileToCommand({ activated: true, launch: false },
                            'script' + exts[0],
                            source),
                            'e'];
                        var opts = {
                            lang: lang.prototype.getId() + '-' +
                                Object.keys(levels)[0],
                            cmds: cmds,
                            hidden: true,
                            floating: true,
                            persistent: false
                        };
                        new CodeBootVM(opts);
                    }
                    loop();
                });
        } else {
            done();
        }
    }

    loop();
};

CodeBoot.prototype.fileToCommand = function (type, filename, content) {

    var typeEncoding = 'u'; // default is unopened file

    if (type) {
        typeEncoding = type.activated ? (type.launch ? 'F' : 'f') : (type.launch ? 'O' : 'o');
    }

    return typeEncoding +
        CodeBoot.prototype.stringToBase64URL(filename) + '~' +
        CodeBoot.prototype.longStringToBase64URL(content);
};

CodeBoot.prototype.zIndexFromLevel = function (level) {
    return 1000 * level;
};

CodeBoot.prototype.registerVM = function (vm) {

    var cb = this;

    vm.zIndex = cb.zIndexFromLevel(cb.vmCount);

    if (vm.zIndex !== 0) {
        vm.root.style.zIndex = vm.zIndex;
    }

    cb.vms[vm.id] = vm;
    cb.vmCount++;
};

CodeBoot.prototype.bringToFront = function (vm) {

    var cb = this;

    var vms = Object.values(cb.vms);

    //console.log('==> ' + vm.zIndex + ' ' + vm.root.style.zIndex + ' ' + cb.zIndexFromLevel(cb.vmCount-1));

    if (vm.zIndex === cb.zIndexFromLevel(cb.vmCount - 1))
        return false;

    vm.zIndex = Infinity;

    cb.refreshZIndex();

    return true;
};

CodeBoot.prototype.refreshZIndex = function () {

    var cb = this;

    var vms = Object.values(cb.vms);

    vms.sort(function (a, b) {
        return (a.zIndex < b.zIndex) ? -1 : 1;
    });

    for (var level = 0; level < vms.length; level++) {
        var vm = vms[level];
        var zIndex = cb.zIndexFromLevel(level);
        vm.zIndex = zIndex;
        vm.root.style.zIndex = zIndex;
    }
};

function getCodeBootVM(elem) {

    var vm = undefined;
    var cb = CodeBoot.prototype.cb;
    var root = null;

    if (elem === undefined) {
        elem = document.body;
    } else {
        root = elem.closest('.cb-vm'); // find enclosing cb-vm element
    }

    if (!root) {
        root = elem.querySelector('.cb-vm'); // find enclosed cb-vm element
    }

    if (root) {
        vm = cb.vms['#' + root.getAttribute('id')];
    }

    return vm;
};

CodeBoot.prototype.longStringToBase64URL = function (str) {
    var bytes = CodeBoot.prototype.longStringToSignedBytes(str);
    return CodeBoot.prototype.bytesToBase64URL(bytes);
};

CodeBoot.prototype.base64URLToString = function (b64) {
    return CodeBoot.prototype.UTF8ToString(
        CodeBoot.prototype.base64URLToBytes(b64));
};

CodeBoot.prototype.base64URLToLongString = function (b64) {
    return CodeBoot.prototype.signedBytesToLongString(
        CodeBoot.prototype.base64URLToSignedBytes(b64));
};

CodeBoot.prototype.bytesToBase64URL = function (bytes) {
    var str = '';
    var len = bytes.length;
    for (var i = 0; i < len; i++) {
        str += String.fromCharCode(bytes[i] & 0xff);
    }
    return CodeBoot.prototype.stringToBase64URL(str);
};

CodeBoot.prototype.base64URLToBytes = function (b64) {
    var str = CodeBoot.prototype.base64URLToString(b64);
    var len = str.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
        bytes[i] = str.charCodeAt(i);
    }
    return bytes;
};

CodeBoot.prototype.base64URLToSignedBytes = function (b64) {
    var str = CodeBoot.prototype.base64URLToString(b64);
    var len = str.length;
    var bytes = new Int8Array(len);
    for (var i = 0; i < len; i++) {
        bytes[i] = ((str.charCodeAt(i) + 128) & 0xff) - 128;
    }
    return bytes;
};

CodeBoot.prototype.stringToBase64URL = function (b64) {
    return btoa(b64).replace(/\+/g, '-').replace(/\//g, '_');
};

CodeBoot.prototype.base64URLToString = function (b64) {
    return atob(b64.replace(/-/g, '+').replace(/_/g, '/'));
};

CodeBoot.prototype.stringToUTF8 = function (str) {
    return new TextEncoder().encode(str);
};

CodeBoot.prototype.UTF8ToString = function (bytes) {
    return new TextDecoder().decode(bytes);
};

CodeBoot.prototype.longStringToSignedBytes = function (str) {
    return LZMA.compress(str);
};

CodeBoot.prototype.signedBytesToLongString = function (bytes) {
    return LZMA.decompress(bytes);
};

CodeBoot.prototype.escapeHTML = function (str) {
    return str.replace(/[&<>"'`]/g, function (chr) {
        return '&#' + chr.charCodeAt(0) + ';';
    });
};

CodeBoot.prototype.unescapeHTML = function (html) {
    return (html
            .replace(/&#96;/g, '`')
            .replace(/&lt;/g, '<')
            .replace(/&#60;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&#62;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#34;/g, '"')
            .replace(/&#39;/g, '\'')
            .replace(/&amp;/g, '&#38;')
            .replace(/&#38;/g, '&'));
};

CodeBoot.prototype.dateToTimeStamp = function (date) {

    function pad2(n) {
        return String(n).padStart(2, '0');
    }

    return pad2(date.getFullYear() % 100) +
        pad2(date.getMonth() + 1) +
        pad2(date.getDate()) +
        'T' + pad2(date.getHours()) +
        pad2(date.getMinutes()) +
        pad2(date.getSeconds());
    /*old:*/
    return date.getFullYear() +
        '-' + pad2(date.getMonth() + 1) +
        '-' + pad2(date.getDate()) +
        'T' + pad2(date.getHours()) +
        pad2(date.getMinutes()) +
        pad2(date.getSeconds());
};

CodeBoot.prototype.isTimeStamp = function (string) {
    return /^\d\d\d\d\d\dT\d\d\d\d\d\d$/.test(string);
    /*old:*/
    return /^\d\d\d\d-\d\d-\d\dT\d\d\d\d\d\d$/.test(string);
};

CodeBoot.prototype.browserType = function () {

    // Taken from https://stackoverflow.com/questions/9847580/how-to-detect-safari-chrome-ie-firefox-and-opera-browsers

    // Opera 8.0+
    //    var isOpera = (!!window.opr && !!opr.addons) || !!window.opera || navigator.userAgent.indexOf(' OPR/') >= 0;

    // Firefox 1.0+
    //    var isFirefox = typeof InstallTrigger !== 'undefined';

    // Safari 3.0+ "[object HTMLElementConstructor]"
    var isSafari = /constructor/i.test(window.HTMLElement) || (function (p) { return p.toString() === "[object SafariRemoteNotification]"; })(!window['safari'] || (typeof safari !== 'undefined' && window['safari'].pushNotification));

    // Internet Explorer 6-11
    //    var isIE = /*@cc_on!@*/false || !!document.documentMode;

    // Edge 20+
    //    var isEdge = !isIE && !!window.StyleMedia;

    // Chrome 1 - 79
    //    var isChrome = !!window.chrome && (!!window.chrome.webstore || !!window.chrome.runtime);

    // Edge (based on chromium) detection
    //    var isEdgeChromium = isChrome && (navigator.userAgent.indexOf("Edg") != -1);

    // Blink engine detection
    //    var isBlink = (isChrome || isOpera) && !!window.CSS;

    // Currently only care about Safari...

    return isSafari ? 'safari' : 'other';
};

CodeBoot.prototype.cb = new CodeBoot();

//-----------------------------------------------------------------------------

// CodeBoot virtual machines encapsulate an execution environment

function CodeBootVM(opts) {

    var vm = this;

    if (opts === undefined)
        opts = {};

    var cb;

    if (opts.cb === undefined)
        cb = CodeBoot.prototype.cb;
    else
        cb = opts.cb;

    var root;

    if (opts.root === undefined)
        root = document.createElement('div');
    else
        root = opts.root;

    var index = ++cb.vmsCreated;
    var id = 'cb-vm-' + index; // default id

    if (root.hasAttribute('id')) {
        id = root.getAttribute('id');
    } else {
        if (opts.id)
            id = opts.id;
        root.setAttribute('id', id);
    }

    function get_option(name, attr, default_value) {
        var result = opts[name];
        if (result === undefined && attr !== null) {
            if (root.hasAttribute(attr)) {
                if (typeof (default_value) === 'boolean') {
                    result = true;
                } else if (typeof (default_value) === 'number') {
                    result = +root.getAttribute(attr);
                } else {
                    result = root.getAttribute(attr);
                }
            } else {
                result = default_value;
            }
        } else if (typeof (result) == 'string') {
            if (typeof (default_value) === 'boolean') {
                result = (result === 'true');
            } else if (typeof (default_value) === 'number') {
                result = +result;
            }
        }
        return result;
    }

    function get_option_attr(name, attr, default_value) {
        var result = get_option(name, attr, default_value);
        vm.setAttribute(attr, result);
        return result;
    }

    function set_options(opts) {
        var cmds = opts.cmds;
        if (cmds) {
            opts.cmds = [];
            for (var i = 0; i < cmds.length; i++) {
                var cmd = cmds[i];
                if (cmd[0] === '~') {
                    var parts = cmd.slice(1).split('=');
                    if (parts.length === 2) {
                        opts[parts[0]] = parts[1];
                    }
                } else {
                    opts.cmds.push(cmd);
                }
            }
        }
    }

    if (opts.cmds === undefined &&
        root.hasAttribute('data-cb-cmds')) {
        opts.cmds = root.getAttribute('data-cb-cmds').split('.');
    }

    set_options(opts);

    id = '#' + id;

    vm.id = id;     // id of this VM, typically '#cb-vm-N'
    vm.cb = cb;     // CodeBoot container
    vm.root = root;   // DOM element with class 'cb-vm'
    vm.index = index;  // sequence number, typically the N in the id
    vm.langs = {};     // language instances in use
    vm.lang = null;   // reference to instance of Lang
    vm.level = null;   // the selected level of the language
    vm.vmClone = null;
    vm.vmCloneOrigin = null;
    vm.isOpen = true;
    vm.privkey = null;

    vm.embedded = get_option_attr('embedded', 'data-cb-embedded', false);
    vm.storageId = get_option_attr('storageId', 'data-cb-storage-id', id);
    vm.minWidth = get_option_attr('minWidth', 'data-cb-min-width', 575);
    vm.minHeight = get_option_attr('minHeight', 'data-cb-min-height', 400);
    vm.resizable = get_option_attr('resizable', 'data-cb-resizable', false);
    vm.resizeListeners = []; // list of function to call upon resize
    vm.editable = get_option_attr('editable', 'data-cb-editable', true);

    get_option_attr('showHeader', 'data-cb-show-header', false);
    get_option_attr('showFooter', 'data-cb-show-footer', false);
    get_option_attr('showConsole', 'data-cb-show-console', false);
    get_option_attr('showReplContainer', 'data-cb-show-repl-container', false);
    get_option_attr('showPlayground', 'data-cb-show-playground', false);
    get_option_attr('showEditors', 'data-cb-show-editors', false);

    get_option_attr('showClone', 'data-cb-show-clone', false);

    new CodeBootFileSystem(vm); // initializes vm.fs

    vm.devMode = false;
    vm.priviledged = false;
    vm.showLineNumbers = undefined;
    vm.largeFont = undefined;
    vm.animationSpeed = undefined;
    vm.stepDelay = normalStepDelay;
    vm.stepDelayForEventHandler = normalStepDelay;
    vm.pauseAtStepCount = Infinity;
    vm.asyncAction = null;

    vm.saveInProgress = false;
    vm.lastFocusedEditor = null;
    vm.allowLosingFocus = true;

    vm.latestProcessEvent = '';
    vm.latestProcessEventRepeat = 0;
    vm.latestExecEvent = '';

    vm.force_reset = true;

    vm.repl = null;
    vm.replFeed = [];
    vm.replFeedCmd = null;

    vm.lastAST = null;
    vm.lastSource = null;
    vm.lastSourceStartPos = null;
    vm.lastSourceEndPos = null;
    vm.lastLaunchFilename = null;
    vm.lastResult = null;
    vm.lastResultRepresentation = null;

    vm.sockets = []; // TODO: belongs elsewhere (in runtime environment)

    vm.setClass('cb-vm', true); // force class in case not yet set

    // get language (default to first registered language and level)
    var id_and_level = get_option('lang', 'data-cb-lang', '');

    id_and_level = Lang.prototype.full(id_and_level);

    vm.setLang(id_and_level);

    var floating =
        get_option_attr('floating', 'data-cb-floating', false);

    var cloned =
        get_option_attr('cloned', 'data-cb-cloned', false);

    var initLast = vm.initRoot(opts, floating, cloned);

    vm.setHidden(
        get_option_attr('hidden', 'data-cb-hidden', false));

    if (opts.root === undefined) {
        var parent;
        if (opts.parent === undefined)
            parent = document.body;
        else
            parent = opts.parent;
        parent.appendChild(vm.root);
    }

    cb.registerVM(vm);

    if (cb.vmsCreated === 1) {
        vm.initCommon(opts);
    }

    vm.setFocusREPL(true); // do this early to avoid background color flicker on execution buttons

    vm.initUI();

    vm.initNet();

    vm.setLangUI();

    vm.setupTooltip();

    vm.setupEventHandlers();

    vm.enterMode(vm.modeStopped());

    vm.replAllowInput();

    vm.setDevMode(
        get_option('devMode', 'data-cb-dev-mode', false));

    vm.setShowLineNumbers(
        get_option('showLineNumbers', 'data-cb-show-line-numbers', false));

    vm.setLargeFont(
        get_option('largeFont', 'data-cb-large-font', false));

    vm.setAnimationSpeed(
        get_option('animationSpeed', 'data-cb-animation-speed', 'normal'));

    vm.setFloating(floating);

    var language =
        get_option_attr('language', 'data-cb-language', null);

    if (language) {
        vm.setLanguage(opts.language);
    } else {
        vm.setUILanguageFromBrowser();
    }

    if (cb.isIsolatedLocation()) {
        vm.setAttribute('data-cb-persistent', false);
        vm.clearAllStorage();
    } else {
        var persistent = get_option('persistent', 'data-cb-persistent', true);
        vm.setAttribute('data-cb-persistent', persistent);
        vm.beginSession();
    }

    vm.replFocus();

    vm.updateUI();

    initLast();

    if (opts.input)
        vm.replSetInput(opts.input);

    if (opts.event)
        vm.execEvent(opts.event);

    if (opts.cmds) {
        vm.execCommands(opts.cmds);
    }

    if (cb.vmsCreated === 1) {
        var handlers = CodeBoot.prototype.onload_handlers;
        CodeBoot.prototype.onload_handlers = [];
        handlers.forEach(function (descr) {
            CodeBoot.prototype.event_handle({ target: descr.elem }, descr.id);
        });
    }
};

CodeBootVM.prototype.onlyFileCommands = function (cmds) {

    var vm = this;

    for (var i = 0; i < cmds.length; i++) {
        var cmd = cmds[i];
        var op = cmd[0];
        if (op !== 'u' &&
            op !== 'f' &&
            op !== 'F' &&
            op !== 'o' &&
            op !== 'O') {
            return false;
        }
    }

    return true;
};

CodeBootVM.prototype.execCommands = function (cmds) {

    var vm = this;

    if (cmds.length > 0 && !vm.onlyFileCommands(cmds)) {
        vm.fs.removeFileEditors();
    }

    vm.execCommandsLoop(cmds, null, null, null, 0);
};

CodeBootVM.prototype.execCommandsLoop = function (cmds, fileToActivate, feed, execCmd, i) {

    var vm = this;

    if (i < cmds.length) {

        var cmd = cmds[i];
        var op = cmd[0];

        switch (op) {

            case 'i': // add input
                fileToActivate = null;
                feed = vm.cb.base64URLToString(cmd.slice(1));
                vm.execCommandsLoop(cmds, fileToActivate, feed, execCmd, i + 1);
                break;

            case 'u': // add file (unopened)
            case 'f': // add file (open, activated and not marked as launch)
            case 'F': // add file (open, activated and marked as launch)
            case 'o': // add file (open, not activated and not marked as launch)
            case 'O': // add file (open, not activated and marked as launch)
                var parts = cmd.slice(1).split('~');
                if (parts.length === 2) {
                    var filename = vm.cb.base64URLToString(parts[0]);
                    var content = vm.cb.base64URLToLongString(parts[1]);
                    vm.fs.createFileNoClobber(filename, content, {}, null, function (file) {
                        // file will be falsy when user cancelled file import
                        if (file) {
                            if (op !== 'u') {
                                vm.fs.openFile(file);
                                file.fe.setLaunch(op === 'O' || op === 'F');
                                if (op === 'f' || op === 'F') {
                                    fileToActivate = file;
                                } else if (fileToActivate !== null) {
                                    fileToActivate.fe.activate();
                                }
                            }
                            vm.execCommandsLoop(cmds, fileToActivate, feed, execCmd, i + 1);
                        }
                    });
                }
                break;

            case 'e': // eval
            case 'a': // animate
                vm.execCommandsLoop(cmds, fileToActivate, feed, cmd, i + 1);
                break;

            case '~': // settings
                var parts = cmd.slice(1).split('=');
                if (parts.length === 2) {
                    switch (parts[0]) {
                        case 'lang':
                            vm.setLang(parts[1]);
                            vm.setLangUI();
                            break;
                        case 'showLineNumbers':
                            vm.setShowLineNumbers(parts[1] === 'true');
                            break;
                        case 'largeFont':
                            vm.setLargeFont(parts[1] === 'true');
                            break;
                        case 'hidden':
                            vm.setHidden(parts[1] === 'true');
                            break;
                        case 'floating':
                            vm.setFloating(parts[1] === 'true');
                            break;
                        case 'animationSpeed':
                            vm.setAnimationSpeed(parts[1]);
                            break;
                        case 'language':
                            vm.setLanguage(parts[1]);
                            break;
                    }
                }
                vm.execCommandsLoop(cmds, fileToActivate, feed, execCmd, i + 1);
                break;
        }
    } else {

        if (fileToActivate) {
            vm.lastFocusedEditor = fileToActivate.fe.textEditor;
        } else {
            vm.lastFocusedEditor = vm.repl;
        }

        if (feed) {
            vm.replSetFeed(feed, execCmd);
            vm.feedREPL();
        } else {
            vm.execEventFromCommand(execCmd);
        }
    }
};

CodeBootVM.prototype.getLocation = function () {

    var vm = this;

    var loc = window.location;
    var location = loc.protocol + '//' + loc.host + loc.pathname;

    return location;
};

CodeBootVM.prototype.toURL = function (type, opts) {

    var vm = this;
    var cmds = [];

    var launchedFilename = vm.isRunning() ? vm.lastLaunchFilename : null; // null when program not running
    var launch = vm.findLaunch(); // filename marked as launch, or null when none marked

    opts = (opts === undefined) ? {} : Object.assign({}, opts);

    function addFile(file) {
        var type = file.defaultType();
        if (type !== null && launch === null && launchedFilename !== null) {
            // if no file is marked as launch, only activate launched file
            // so that it will be the one loaded first
            type.activated = file.filename === launchedFilename;
        }
        cmds.push(file.toCommand(type));
    }

    if (type === 'image') {

        // add files not open in an editor tab first (because order is irrelevant)

        vm.fs.each(function (file) {
            if (!file.fe.isEnabled()) addFile(file);
        });
    }

    // add files open in an editor tab (because order is relevant)

    vm.forEachElem('.cb-file-tab', function (elem) {
        var filename = elem.getAttribute('data-cb-file-tab-filename');
        if (filename) {
            var file = vm.fs.getByName(filename);
            if (file) addFile(file);
        }
    });

    cmds.push('~lang=' + vm.getAttribute('data-cb-lang'));

    if (opts.language) {
        cmds.push('~language=' + opts.language)
    }

    if (vm.hasAttribute('data-cb-show-line-numbers')) {
        cmds.push('~showLineNumbers=true');
    }

    if (vm.hasAttribute('data-cb-large-font')) {
        cmds.push('~largeFont=true');
    }

    //TODO: decide if language setting should be bundled in URL
    //    var language = vm.getLanguage();
    //
    //    if (language) {
    //        cmds.push('~language=' + language);
    //    }

    if (type === 'webapp' || vm.isHidden()) {
        cmds.push('~hidden=true');
    }

    if (type !== 'webapp' && vm.isFloating()) {
        cmds.push('~floating=true');
    }

    function addInput(source) {
        cmds.push('i' + CodeBoot.prototype.stringToBase64URL(source));
    }

    if (vm.isRunning()) {
        if (vm.lastLaunchFilename === null) {
            // execution was started from REPL
            addInput(vm.replGetHistorySinceReset(false));
        }
    } else if (vm.repl && vm.lastFocusedEditor === vm.repl) {
        // execution is stopped, but REPL is focused
        addInput(vm.replGetHistorySinceReset(true));
    }

    var op = 'e';

    if (type === 'animate') {
        op = 'a';
        if (vm.animationSpeed !== 'normal') {
            cmds.push('~animationSpeed=' + vm.animationSpeed);
        }
    }

    if (type !== 'webapp' &&
        type !== 'execute' &&
        vm.ui.mode === vm.modeStepping()) {
        var steps = vm.lang.getStepCount();
        cmds.push(op + steps);
    } else if (type === 'step') {
        cmds.push(op + '1');
    } else if (type !== 'bundle' && type !== 'image') {
        cmds.push(op);
    }

    //    console.log('###### type = ' + type);

    //    for (var i=0; i<cmds.length; i++) {
    //        console.log('###### cmds[' + i + '] = |' + cmds[i] + '|');
    //    }

    return vm.commandsToURL(cmds, false);
};

CodeBoot.prototype.commandsToSign = function (cmds) {

    var cb = this;

    return cmds.filter(function (cmd) { return !cmd.startsWith('~~'); });
};

CodeBootVM.prototype.commandsToURL = function (cmds, isolated) {

    var vm = this;
    var cmds_str = CodeBoot.prototype.cb.commandsToSign(cmds).join('.');
    var signature = '';

    if (vm.priviledged && vm.privkey !== null) {
        var sig = CodeBoot.prototype.signString(cmds_str, vm.privkey);
        if (sig === null) {
            isolated = true;
        } else {
            signature = sig;
        }
    } else {
        isolated = true;
    }

    var location = vm.cb.getCodeBootLocation(isolated);

    var url = location + "?" + vm.cb.commandsQueryParam + "=" + signature + '.' + cmds_str;

    console.log('url.length = ' + url.length);

    //TODO: choose an appropriate limit
    //    if (url.length > 8000) return null; // refuse to create long URLs

    return url;
};

