CodeBootVM.prototype.setLang = function (id_and_level) { // sets programming language

    var vm = this;
    var x = Lang.prototype.split(id_and_level);
    var id = x.id;
    var level = x.level;

    vm.lang = vm.loadLang(id); // load language
    vm.level = level;

    vm.setAttribute('data-cb-lang', id_and_level);
};

CodeBootVM.prototype.setLangUI = function () {

    var vm = this;
    var id_and_level = vm.lang.getId() + '-' + vm.level;

    // Update UI to reflect selected language

    vm.setCheckmark('data-cb-setting-lang', id_and_level, true);

    var images = vm.lang.getImages(vm.level);

    vm.forEachElem('.cb-lang-on-light', function (elem) {
        elem.innerHTML = images.onLight;
    });

    vm.forEachElem('.cb-lang-on-dark', function (elem) {
        elem.innerHTML = images.onDark;
    });

    vm.replSetup(); // initializes vm.repl
};

CodeBootVM.prototype.setLanguage = function (language) { // sets natural language

    var vm = this;

    vm.setAttribute('lang', language);

    var about = document.querySelector('#cb-about-box');

    if (about) {
        about.setAttribute('lang', language);
    }

    var help = document.querySelector('#cb-help-box');

    if (help) {
        help.setAttribute('lang', language);
    }
};

