CodeBootVM.prototype.initRoot = function (opts, floating, cloned) {

    var vm = this;
    var nChildren = vm.root.childNodes.length;
    var filename = undefined;
    var content = null;

    function initLast() {

        vm.setAttribute('data-cb-editable', vm.editable);

        if (content !== null) {
            vm.fs.newFile(filename, content);
        }

        // In order to resize the repl's height, the CodeMirror-scroll
        // element's max-height must be explicitly changed

        var bodyElem = vm.root.querySelector('.cb-body');
        if (bodyElem) {
            var replContElem = bodyElem.querySelector('.cb-repl-container');
            if (replContElem) {
                vm.setupSplitter(bodyElem, function (size) {
                    var replScrollElem = replContElem.querySelector('.CodeMirror-scroll');
                    if (replScrollElem) {
                        replScrollElem.style.maxHeight = size + 'px';
                        vm.replScrollToEnd();
                    }
                });
            }
        }

        vm.root.querySelector('.CodeMirror').CodeMirror.refresh()

        var consoleElem = vm.root.querySelector('.cb-console');
        if (consoleElem) {
            vm.setupSplitter(consoleElem);
        }

        vm.forEachElem('[data-cb-exec-link]', function (elem) {
            var val = elem.getAttribute('data-cb-exec-link');
            elem.addEventListener('click', function (event) {
                var url = vm.toURL(val);
                window.open(url, '_blank');
                return false;
            });
        });

        vm.initRootLastHook();
    }

    function copyCloneCmds(src, dst) {
        var val = src.getAttribute('data-cb');
        if (val) {
            dst.setAttribute('data-cb-clone-cmds', val);
        }
    }

    if (vm.root.tagName === 'PRE') {

        content = vm.root.innerText;

        var lines = content.split('\n');
        if (lines[lines.length-1].trim().length === 0) lines.pop();
        content = lines.join('\n');

        var outer = document.createElement('div');
        var elem = outer;
        var cssText = vm.root.style.cssText;

        if (cssText) {
            elem = document.createElement('div');
            outer.appendChild(elem);
            outer.style.cssText = cssText;
        }

        copyCloneCmds(vm.root, elem);

        elem.className = 'cb-vm';

        elem.innerHTML =
            vm.bodyHTML(true, false) +
            vm.execControlsHTML(false, true) +
            vm.localHTML();

        vm.root.replaceWith(outer);
        vm.root = elem;

        vm.setAttribute('data-cb-show-editors', true);
        vm.setAttribute('data-cb-runable-code', true);

        vm.embedded = true
        vm.editable = (content === null);

    } else if (nChildren === 0) {

        vm.root.innerHTML =
            vm.headerHTML() +
            vm.navbarHTML(true, cloned, false) +
            vm.bodyHTML(false, true) +
            vm.footerHTML() +
            vm.resizeHandleHTML() +
            vm.localHTML();

        vm.setAttribute('data-cb-show-console', true);
        vm.setAttribute('data-cb-show-repl-container', true);
        vm.setAttribute('data-cb-show-editors', true);

        vm.editable = true;

        if (opts.filename !== undefined)
            filename = opts.filename;

        if (opts.content !== undefined)
            content = opts.content;

    } else if (nChildren === 1) {

        var child = vm.root.childNodes[0];

        if (child.tagName === 'PRE') {

            content = child.innerText;

            vm.root.innerHTML =
                vm.execControlsHTML(false, true) +
                vm.bodyHTML(true, false) +
                vm.localHTML();

            vm.setAttribute('data-cb-show-editors', true);
            vm.setAttribute('data-cb-runable-code', true);
        }

        vm.editable = (content === null);
    }

    vm.setAttribute('data-cb-embedded', vm.embedded);

    vm.initRootHook(opts, floating, cloned);

    return initLast;
};

CodeBootVM.prototype.initRootHook = function (opts, floating, cloned) {
};

CodeBootVM.prototype.initRootLastHook = function () {
};

CodeBootVM.prototype.initCommon = function (opts) {

    var vm = this;

    var scope = document.body;
    var common = document.createElement('div');

    //    common.innerHTML = vm.menuContextHTML() + vm.helpHTML();
    common.innerHTML = vm.helpHTML();

    var ctxmenu = common.querySelector('.cb-menu-context');

    //TODO: remove contextual menu handling and CSS

    if (ctxmenu) {

        var bundle_webapp_url = null;
        var bundle_files_url = null;
        var bundle_step_url = null;
        var bundle_animate_url = null;
        var bundle_execute_url = null;

        function dismiss(event) {
            ctxmenu.style.display = 'none';
        }

        common.querySelectorAll('.dropdown-item').forEach(function (elem) {

            function dropdownItem(event) {
                var elem = event.currentTarget;
                var val;

                if (val = elem.getAttribute('data-cb-context-presentation')) {
                    if (val === 'hidden') {
                        vm.setHidden(true);
                    } else if (val === 'floating') {
                        vm.setHidden(false);
                        vm.setFloating(true);
                    } else {
                        vm.setHidden(false);
                        vm.setFloating(false);
                    }
                } else if (elem.hasAttribute('data-cb-context-bundle-web-app')) {
                    vm.copyTextToClipboard(bundle_webapp_url);
                    vm.focusLastFocusedEditor();
                } else if (elem.hasAttribute('data-cb-context-bundle-files')) {
                    vm.copyTextToClipboard(bundle_files_url);
                    vm.focusLastFocusedEditor();
                } else if (elem.hasAttribute('data-cb-context-bundle-step')) {
                    vm.copyTextToClipboard(bundle_step_url);
                    vm.focusLastFocusedEditor();
                } else if (elem.hasAttribute('data-cb-context-bundle-animate')) {
                    vm.copyTextToClipboard(bundle_animate_url);
                    vm.focusLastFocusedEditor();
                } else if (elem.hasAttribute('data-cb-context-bundle-execute')) {
                    vm.copyTextToClipboard(bundle_execute_url);
                    vm.focusLastFocusedEditor();
                }
                dismiss(event);
                event.stopPropagation();
                event.preventDefault();
            }

            elem.addEventListener('click', dropdownItem);
        });

        ctxmenu.addEventListener('pointerleave', dismiss);

        function open(event) {

            var vm = getCodeBootVM(event.target);

            function done() {
                var language = vm.getLanguage();
                if (language) {
                    ctxmenu.setAttribute('lang', language);
                }
                if (vm.priviledged) {
                    ctxmenu.setAttribute('data-cb-priviledged', true);
                } else {
                    ctxmenu.removeAttribute('data-cb-priviledged');
                }
                ctxmenu.querySelectorAll('.cb-svg-checkmark').forEach(function (elem) {
                    elem.style.visibility = 'hidden';
                });
                var elem = null;
                if (vm.isHidden()) {
                    elem = ctxmenu.querySelector('[data-cb-context-presentation="hidden"] .cb-svg-checkmark');
                } else if (vm.isFloating()) {
                    elem = ctxmenu.querySelector('[data-cb-context-presentation="floating"] .cb-svg-checkmark');
                } else {
                    elem = ctxmenu.querySelector('[data-cb-context-presentation="full"] .cb-svg-checkmark');
                }
                if (elem) {
                    elem.style.visibility = 'visible';
                }
                elem = ctxmenu.querySelector('a[data-cb-context-bundle-web-app]');
                if (elem && bundle_webapp_url === null) {
                    elem.style.display = 'none';
                } else {
                    elem.removeAttribute('style');
                }
                elem = ctxmenu.querySelector('a[data-cb-context-bundle-files]');
                if (elem && bundle_files_url === null) {
                    elem.style.display = 'none';
                } else {
                    elem.removeAttribute('style');
                }
                elem = ctxmenu.querySelector('a[data-cb-context-bundle-step]');
                if (elem && bundle_step_url === null) {
                    elem.style.display = 'none';
                } else {
                    elem.removeAttribute('style');
                }
                elem = ctxmenu.querySelector('a[data-cb-context-bundle-animate]');
                if (elem && bundle_animate_url === null) {
                    elem.style.display = 'none';
                } else {
                    elem.removeAttribute('style');
                }
                elem = ctxmenu.querySelector('a[data-cb-context-bundle-execute]');
                if (elem && bundle_execute_url === null) {
                    elem.style.display = 'none';
                } else {
                    elem.removeAttribute('style');
                }
                elem = ctxmenu.querySelector('div.cb-bundle-to-clipboard');
                if (elem) {
                    if (bundle_webapp_url === null &&
                        bundle_files_url === null &&
                        bundle_step_url === null &&
                        bundle_animate_url === null &&
                        bundle_execute_url === null) {
                        elem.style.display = 'none';
                    } else {
                        elem.removeAttribute('style');
                    }
                }
                ctxmenu.style.left = (event.pageX - 15) + 'px';
                ctxmenu.style.top = (event.pageY - 15) + 'px';
                ctxmenu.style.display = 'block';
            }

            if (event.pointerType === 'mouse' && !event.altKey)
                return; // ignore if alt key not pressed

            if (vm &&
                !(event.target.closest('.cb-drawing-window') ||
                    event.target.closest('.cb-pixels-window'))) {

                event.stopPropagation();
                event.preventDefault();

                if (ctxmenu.style.display === 'none') {
                    bundle_webapp_url = vm.toURL('webapp');
                    bundle_files_url = vm.toURL('files');
                    bundle_step_url = vm.toURL('step');
                    bundle_animate_url = vm.toURL('animate');
                    bundle_execute_url = vm.toURL('execute');
                    done();
                }
            }
        }

        scope.addEventListener('contextmenu', open);

        scope.addEventListener('touchstart', function (event) {
            if (event.touches.length === 4) {
                event.preventDefault();
                open(event);
            }
        });
    }

    scope.appendChild(common);

    setupHelp();
};

CodeBoot.prototype.hasTouchInterface = function () {
    return ('ontouchstart' in window) ||
           (navigator.maxTouchPoints > 0) ||
           (navigator.msMaxTouchPoints > 0);
};

CodeBootVM.prototype.setupSplitter = function (containerElem, setSize) {

    function px(style, property) {
        return parseInt(style.getPropertyValue(property).slice(0, -2));
    }

    if (!containerElem) return;

    var rigidElem = containerElem.querySelector(':scope > .cb-pane-rigid');
    var elasticElem = containerElem.querySelector(':scope > .cb-pane-elastic');
    var splitterElem = containerElem.querySelector(':scope > .cb-pane-splitter');

    if (!(rigidElem && elasticElem && splitterElem)) return;

    var rigidPaneLast = splitterElem.nextElementSibling === rigidElem;
    var containerStyle = window.getComputedStyle(containerElem);
    var rigidStyle = window.getComputedStyle(rigidElem);
    var elasticStyle = window.getComputedStyle(elasticElem);

    var vert = containerStyle.getPropertyValue('flex-direction') === 'column';
    var sizeProp = vert ? 'height' : 'width';
    var sizeMinProp = vert ? 'min-height' : 'min-width';

    var rigidSizeMin = px(rigidStyle, sizeMinProp);
    var elasticSizeMin = px(elasticStyle, sizeMinProp);

    var startPos = null;
    var startSize = null;
    var currentSize = null;
    var maxSize = px(containerStyle, sizeProp);

    //console.log(rigidElem);
    //console.log(rigidStyle.getPropertyValue('height'));

    rigidElem.style.flexBasis = rigidStyle.getPropertyValue('height');


    function setSizeSafe(size) {
        var rigidSizeMin = px(rigidStyle, sizeMinProp);
        var elasticDisplay = elasticStyle.getPropertyValue('display') != 'none'
        var elasticSizeMin = elasticDisplay && px(elasticStyle, sizeMinProp);
        var margins = 8 * 3; // magic values

        //console.log(maxSize)

        if (!elasticDisplay) margins = 8;


        var size = Math.max(rigidSizeMin, size);
        var size = Math.min(maxSize - elasticSizeMin - margins, size);

        if (setSize) setSize(size);
        rigidElem.style.flexBasis = size + 'px';
    }


    function resizeParent(elasticSizeMin = false) {
        maxSize = px(containerStyle, sizeProp, elasticSizeMin);
        if (currentSize !== null) {
            setSizeSafe(currentSize);
        }
    }

    function mouseDown(event) {
        startPos = vert ? event.pageY : event.pageX;
        startSize = px(rigidStyle, sizeProp);
        currentSize = startSize;
        document.body.addEventListener('pointermove', mouseMove);
        document.body.addEventListener('pointerup', mouseEnd);
        event.preventDefault();
    }

    function mouseMove(event) {
        if (event.buttons && startPos !== null) {
            var elasticSize = px(elasticStyle, sizeProp);
            var elasticDisplay = elasticStyle.getPropertyValue('display') != 'none'
            var elasticSizeMin = elasticDisplay && px(elasticStyle, sizeMinProp);
            var rigidSizeMin = px(rigidStyle, sizeMinProp);
            var pos = vert ? event.pageY : event.pageX;
            var dist = pos - startPos;
            if (rigidPaneLast) dist = -dist;
            var delta = dist - (currentSize - startSize);
            var size = Math.max(rigidSizeMin, delta + currentSize);
            //console.log(elasticSize, pos, dist, delta, size);
            rigidElem.style.flexBasis = size + 'px';
            var size = delta + currentSize;
            if (setSize) setSizeSafe(size);
            currentSize = size;
        } else {
            mouseEnd();
        }
        event.preventDefault();
    }

    function mouseEnd(event) {
        startPos = null;
        document.body.removeEventListener('pointerup', mouseEnd);
        splitterElem.removeEventListener('pointermove', mouseMove);
    }

    splitterElem.addEventListener('pointerdown', mouseDown);

    var vm = this;
    vm.resizeListeners.push(resizeParent);
};

// UI events

CodeBootVM.prototype.unload = function () {
    var vm = this;
    vm.saveSession();
};

CodeBootVM.prototype.splitLines = function (str) {
    var lines = str.split('\r\n');
    if (lines.length === 1) {
        lines = str.split('\n');
    }
    if (lines[lines.length - 1] === '') lines.pop();
    return lines;
};

CodeBootVM.prototype.handleDrop = function (event) {

    var vm = this;
    var dt = event.dataTransfer;

    event.preventDefault();
    event.stopPropagation();

    var opts = {};
    var suffix = null;
    var open = true;

    console.log('=================== dt.types = |' + dt.types.join('|') + '|');

    if ('files' in dt && dt.files.length > 0) {
        vm.addDroppedFiles(dt.files, opts, suffix, open);
    } else {

        function extractLines(str, fn) {
            return CodeBootVM.prototype.splitLines(str).filter(fn);
        }

        if (dt.types.indexOf('text/x-moz-url') >= 0) {
            vm.dropURIList(extractLines(dt.getData('text/x-moz-url'),
                function (line, i) {
                    return i % 2 === 0;
                }));
        } else if (dt.types.indexOf('text/uri-list') >= 0) {
            vm.dropURIList(extractLines(dt.getData('text/uri-list'),
                function (line) {
                    return !line.startsWith('#');
                }));
        } else {
            var type = null;
            var filename = null;
            var input = null;
            var HTML = null;
            var URL = null;
            var content = '';
            var cmds = [];

            if (dt.types.indexOf('text/html') >= 0) {
                HTML = dt.getData('text/html');
                type = CodeBoot.prototype.extractMetaInfo(HTML, CodeBoot.prototype.typeMetaInfo);
                if (type !== null) {
                    // HTML was created by codeBoot
                    filename = CodeBoot.prototype.extractMetaInfo(HTML, CodeBoot.prototype.filenameMetaInfo);
                    input = CodeBoot.prototype.extractMetaInfo(HTML, CodeBoot.prototype.inputMetaInfo);
                    URL = CodeBoot.prototype.extractMetaInfo(HTML, CodeBoot.prototype.URLMetaInfo);
                }
            }

            if (dt.types.indexOf('text/plain') >= 0) {
                content = dt.getData('text/plain');
            }

            console.log('=================== type     = |' + type + '|');
            console.log('=================== filename = |' + filename + '|');
            console.log('=================== input    = |' + input + '|');
            console.log('=================== content  = |' + content + '|');
            console.log('=================== HTML     = |' + HTML + '|');
            console.log('=================== URL      = |' + URL + '|');

            if (URL) {
                vm.dropURIList([URL]);
            } else if (content) {
                vm.fs.createFileNoClobber(filename, content, opts, suffix, function (file) {
                    if (open && file) {
                        vm.fs.openFile(file);
                    }
                });
            }
        }
    }
};

CodeBoot.prototype.encodeMetaInfo = function (value, metaInfoBrackets) {
    return metaInfoBrackets.start +
        CodeBoot.prototype.escapeHTML(value) +
        metaInfoBrackets.end;
};

CodeBoot.prototype.extractMetaInfo = function (HTML, metaInfoBrackets) {

    var start = HTML.indexOf(metaInfoBrackets.start);

    if (start >= 0) {
        start += metaInfoBrackets.start.length;
        var end = HTML.indexOf(metaInfoBrackets.end, start);
        if (end >= 0) {
            return CodeBoot.prototype.unescapeHTML(HTML.slice(start, end));
        }
    }

    return null;
};

CodeBoot.prototype.typeMetaInfo = {
    start: ' data-codeboot-type="',
    end: '"',
};

CodeBoot.prototype.filenameMetaInfo = {
    start: ' data-codeboot-file-name="',
    end: '"',
};

CodeBoot.prototype.inputMetaInfo = {
    start: ' data-codeboot-input="',
    end: '"',
};

CodeBoot.prototype.URLMetaInfo = {
    start: ' href="',
    end: '"',
};

CodeBootVM.prototype.addDroppedFiles = function (droppedFiles, opts, suffix, open, cont, i) {

    var vm = this;

    if (i === undefined) {
        i = 0;
    }

    if (i < droppedFiles.length) {
        vm.readDroppedFile(droppedFiles[i], function (files, containerFilename) {
            vm.addFiles(files, opts, suffix, open, 0, function () {
                vm.addDroppedFiles(droppedFiles, opts, suffix, open, cont, i + 1);
            });
        });
    }
};

CodeBootVM.prototype.readDroppedFile = async function (file, cont) {

    var vm = this;

    var files = null;

    var filename;

    if ('name' in file) {
        filename = file.name;
    } else if ('fileName' in file) {
        filename = file.fileName;
    } else {
        filename = vm.translateToCurrentLang('untitled');
    }

    try {
        files = await vm.filesFromZipBlob(file);
    }
    catch (e) {
        //console.log(e);
    }

    if (files) {
        cont(files, filename);
    } else {

        var reader = new FileReader();

        reader.addEventListener('loadend', function () {
            var data = new Uint8Array(reader.result);
            cont([{ filename: filename, data: data }], null);
        });

        reader.readAsArrayBuffer(file);
    }
};

CodeBootVM.prototype.addFiles = function (files, opts, suffix, open, i, cont) {

    var vm = this;

    if (i === undefined) {
        i = 0;
    }

    if (i < files.length) {

        var f = files[i];
        var data = f.data;
        var filename = f.filename;
        var content = null;

        if (!vm.fs.isHiddenFilename(filename) || vm.priviledged) {
            content = decodeFileAsPNG(data) || decodeFileAsUTF8(data);
        }

        if (content === null) {
            vm.addFiles(files, opts, suffix, open, i + 1, cont);
        } else {
            vm.processCertificate(filename, content, function (isCertificate) {
                if (isCertificate) {
                    vm.addFiles(files, opts, suffix, open, i + 1, cont);
                } else {
                    vm.fs.createFileNoClobber(filename, content, opts, suffix, function (file) {
                        if (open && file) {
                            vm.fs.openFile(file);
                        }
                        vm.addFiles(files, opts, suffix, open, i + 1, cont);
                    });
                }
            });
        }
    } else {
        cont();
    }
};

CodeBootVM.prototype.processCertificate = function (filename, content, cont) {

    var vm = this;

    var ext = CodeBootFile.prototype.extension(filename);

    if (ext === '.pem') {
        var lines = CodeBootVM.prototype.splitLines(content);
        if (lines.length >= 2 &&
            lines[0] === '#codeBoot certificate' &&
            lines[1] === '-----BEGIN RSA PRIVATE KEY-----') {
            vm.setCertificate(content); // will fail if certificate is invalid
            cont(true);
            return;
        }
    }

    cont(false);
};

function decodeFileAsPNG(data) {

    var result = null;

    try {
        var png = UPNG.decode(data);
        var rgba8 = new Uint8Array(UPNG.toRGBA8(png)[0]);
        var i = 0;
        var rows = [];
        for (var y = 0; y < png.height; y++) {
            var row = [];
            for (var x = 0; x < png.width; x++) {
                var rgb = { r: 0, g: 0, b: 0 };
                rgb.r = rgba8[i++] >> 4;
                rgb.g = rgba8[i++] >> 4;
                rgb.b = rgba8[i++] >> 4;
                if (rgba8[i++] === 0) {
                    row.push('    ');
                } else {
                    row.push(convertRGB4(rgb));
                }
            }
            rows.push(row.join(''));
        }
        result = rows.join('\n');
    }
    catch (e) {
        //console.log(e);
    }

    return result;
}

function decodeFileAsUTF8(data) {

    var result = '';
    var i = 0;
    var c = 0;
    var c1 = 0;
    var c2 = 0;

    // If we have a BOM skip it
    if (data.length >= 3 &&
        data[0] === 0xef && data[1] === 0xbb && data[2] === 0xbf) {
        i = 3;
    }

    while (i < data.length) {
        c = data[i];

        if (c < 128) {
            result += String.fromCharCode(c);
            i++;
        } else if (c > 191 && c < 224) {
            if (i + 1 >= data.length) {
                return null; //throw 'UTF-8 Decode failed. Two byte character was truncated.';
            }
            c2 = data[i + 1];
            result += String.fromCharCode(((c & 31) << 6) | (c2 & 63));
            i += 2;
        } else {
            if (i + 2 >= data.length) {
                return null; //throw 'UTF-8 Decode failed. Multi byte character was truncated.';
            }
            c2 = data[i + 1];
            c3 = data[i + 2];
            result += String.fromCharCode(((c & 15) << 12) | ((c2 & 63) << 6) | (c3 & 63));
            i += 3;
        }
    }

    return result;
}

CodeBootVM.prototype.dropURIList = function (URIList) {

    var vm = this;
    var cb = vm.cb;

    var all_safe = true;
    var cmds = [];

    for (var i = 0; i < URIList.length; i++) {
        var cmds_from_uri = cb.extractCommands(URIList[i]);
        all_safe = all_safe && cmds_from_uri[0];
        cmds = cmds.concat(cmds_from_uri.slice(1));
    }

    all_safe = all_safe || vm.onlyFileCommands(cmds);

    if (all_safe || cb.isIsolatedLocation()) {
        vm.reset();
        if (!all_safe) {
            vm.setPersistent(false);
            vm.fs.init();
        }
        vm.execCommands(cmds);
    } else {
        vm.confirmHTML(vm.polyglotHTML('You are importing an unsafe link that may cause a loss of privacy. The private data in this browser tab, such as the files, could be altered or sent to an external party if this link were to be imported. You must use a codeBoot certificate to create safe links that can be imported without this warning. Do you want to open the link in a separate browser tab?'),
            function (yes) {
                if (yes) {
                    var url = vm.commandsToURL(cmds, true);
                    if (url) {
                        window.open(url);
                    }
                }
            },
            true); // Cancel is default
    }
};

