CodeBootVM.prototype.askHTML = function (html, answers, cont) {

    var vm = this;

    var dialog = vm.root.querySelector('.cb-modal-dialog');
    var body = dialog && dialog.querySelector('.modal-body');
    var footer = dialog && dialog.querySelector('.modal-footer');

    if (body && footer) {

        body.innerHTML = html;

        var answer = null;
        var primaryAnswer = null;

        function setupButton(name) {

            var but = document.createElement('button');
            var primary = name.startsWith('!');

            if (primary) {
                name = name.slice(1);
                primaryAnswer = name;
            }

            but.className = 'btn ' + (primary ? 'btn-primary' : 'btn-secondary');
            but.innerHTML = vm.polyglotHTML(name);

            if (name === 'Cancel') {
                but.setAttribute('data-dismiss', 'modal');
            } else {
                but.addEventListener('click', function (event) {
                    answer = name;
                    $(dialog).modal('hide');
                });
            }

            footer.appendChild(but);
        }

        footer.innerHTML = '';

        for (var i = 0; i < answers.length; i++) {
            setupButton(answers[i]);
        }

        var prevFocusedEditor = vm.focusEditor(null); // allow focus to leave editor

        function handle_enter(event) {
            if (event.key === 'Enter' || event.keyCode === 13) {
                event.preventDefault();
                event.stopPropagation();
                answer = primaryAnswer;
                $(dialog).modal('hide');
            }
        }

        if (primaryAnswer !== null) {
            dialog.addEventListener('keydown', handle_enter);
        }

        $(dialog).on('hidden.bs.modal', function (event) {
            if (primaryAnswer !== null) {
                dialog.removeEventListener('keydown', handle_enter);
            }
            $(dialog).modal('dispose');
            body.innerHTML = '';
            footer.innerHTML = '';
            vm.focusEditor(prevFocusedEditor);
            cont(answer);
        });

        $(dialog).modal({}); // show the modal dialog
    }
};

CodeBootVM.prototype.confirmHTML = function (html, cont, defaultCancel) {

    var vm = this;

    if (!cont) cont = function (yes) { };

    vm.askHTML(html,
        defaultCancel ? ['!Cancel', 'OK'] : ['Cancel', '!OK'],
        function (answer) {
            cont(answer === 'OK');
        });
};

CodeBootVM.prototype.promptHTML = function (html, cont) {

    var vm = this;

    var dialog = vm.root.querySelector('.cb-modal-dialog');
    var body = dialog && dialog.querySelector('.modal-body');
    var footer = dialog && dialog.querySelector('.modal-footer');

    if (!cont) cont = function () { };

    if (!body || !footer) {
        // use the builtin prompt, which is unfortunately synchronous
        // and doesn't handle HTML
        cont(window.prompt(html));
    } else {

        body.innerHTML = html + '<br><br>';

        var has_confirmed_ok = false;

        function confirm_ok() {
            has_confirmed_ok = true;
            $(dialog).modal('hide');
        }

        var input = document.createElement('input');
        input.className = 'cb-prompt-input';
        body.appendChild(input);

        var cancel = document.createElement('button');
        cancel.className = 'btn btn-secondary';
        cancel.setAttribute('data-dismiss', 'modal');
        cancel.innerHTML = vm.polyglotHTML('Cancel');

        var ok = document.createElement('button');
        ok.className = 'btn btn-primary';
        ok.innerHTML = vm.polyglotHTML('OK');

        ok.addEventListener('click', confirm_ok);

        footer.innerHTML = '';
        footer.appendChild(cancel);
        footer.appendChild(ok);

        var prevFocusedEditor = vm.focusEditor(null); // allow focus to leave editor

        $(dialog).on('shown.bs.modal', function (event) {
            input.focus();
        });

        function handle_enter(event) {
            if (event.key === 'Enter' || event.keyCode === 13) {
                event.preventDefault();
                event.stopPropagation();
                confirm_ok();
            }
        }

        $(dialog).on('hidden.bs.modal', function (event) {
            input.removeEventListener('keydown', handle_enter);
            $(dialog).modal('dispose');
            body.innerHTML = '';
            footer.innerHTML = '';
            vm.focusEditor(prevFocusedEditor);
            if (has_confirmed_ok) {
                cont(input.value);
            } else {
                cont(null);
            }
        });

        input.addEventListener('keydown', handle_enter);

        $(dialog).modal({}); // show the modal dialog
    }
};

CodeBootVM.prototype.alertHTML = function (html, cont) {

    var vm = this;

    if (!cont) cont = function () { };

    vm.askHTML(html,
        ['!OK'],
        function (answer) {
            cont();
        });
};

