CodeBootVM.prototype.setAttribute = function (attr, value) {

    var vm = this;

    if (value === true)
        vm.root.setAttribute(attr, '');
    else if (value === false)
        vm.root.removeAttribute(attr);
    else
        vm.root.setAttribute(attr, value);
};

