function cb_internal_getBounds($element) {
    var offset = $element.offset();
    var w = $element.width();
    var h = $element.height();
    return {
        left: offset.left,
        top: offset.top,
        width: w,
        clientWidth: w,
        height: h,
        clientHeight: h
    };
}

CodeBootVM.prototype.replFocus = function () {

    var vm = this;

    if (!vm.repl) return;

    //    vm.replInput.focus();
    vm.repl.focus();
};

CodeBootVM.prototype.focusDestroyed = function () {

    var vm = this;

    vm.replFocus();
};

CodeBootVM.prototype.containsElement = function (element) {
    // An element is in codeBoot if it is in the codeBoot VM, but not in 
    // the codeBoot HTML playground.
    // TODO: is it correct for multiple VMs in page?
    var vm = this;
    
    var playground = vm.root.querySelector('.cb-html-window');

    return vm.root.contains(element) && ! playground.contains(element);
}

CodeBootVM.prototype.focusLastFocusedEditor = function () {

    var vm = this;

    var focused = document.activeElement;

    if (focused && !vm.containsElement(focused)) {
        // This prevent stealing focus from elements generated by the user
        // for example for an app
        return
    }

    if (vm.lastFocusedEditor !== null) {
        vm.lastFocusedEditor.focus();
    }
};

CodeBootVM.prototype.focusEditor = function (textEditor) {

    var vm = this;

    if (textEditor !== null && textEditor !== vm.repl) {
        if (!textEditor.cb.file.fe.isEnabled()) {
            textEditor = vm.repl;
        }
    }

    var prevFocusedEditor = vm.lastFocusedEditor;

    vm.lastFocusedEditor = textEditor;
    vm.focusLastFocusedEditor();

    return prevFocusedEditor;
};

