CodeBootVM.prototype.flushSockets = function () {
    var vm = this;

    vm.sockets.forEach(function (socket) {
        console.log("disconnecting", socket);
        socket.disconnect();
    })

    vm.sockets = [];
}

CodeBootVM.prototype.registerSocket = function (address, params) {
    var vm = this;

    var socket = io.connect(address, params);

    socket.on("connect", function () {
        socket.prependAny(function () {
            vm.net.addTrafficCount(0, 1);
        })
    })

    function countTraffic(key) {
        var prop = socket[key];

        socket[key] = function (...args) {
            vm.net.addTrafficCount(1, 0);

            if (args.length > 0) {
                var last = args[args.length - 1];
                if (typeof last === 'function') {
                    var patched_callback = function (...args) {
                        vm.net.addTrafficCount(0, 1);
                        return last(...args);
                    }
                    args[args.length - 1] = patched_callback;
                }
            }

            return Reflect.apply(prop, socket, args);
        }
    }

    countTraffic("send");
    countTraffic("emit");

    vm.sockets.push(socket);

    return socket;
}

CodeBootVM.prototype.disconnectSocket = function (socket) {
    var vm = this;

    socket.disconnect();

    var index = vm.sockets.indexOf(socket);

    if (index > -1) {
        vm.sockets.splice(index, 1);
        return true;
    }

    return false;
}

CodeBoot.prototype.setupKeys = function (keys) {

    try {
        for (var i=0; i<keys.length; i++) {
            if (typeof keys[i] === 'string') {
                keys[i] = KEYUTIL.getKey(keys[i]);
            }
        }
    } catch (exc) {
        keys = [];
    }

    return keys;
};

CodeBoot.prototype.signString = function (str, key) {

    var algorithm = CodeBoot.prototype.signAlgorithm;

    try {
        var signature = new KJUR.crypto.Signature({ 'alg': algorithm });
        signature.init(key);
        signature.updateString(str);
        return hextob64u(signature.sign());
    } catch (exc) {
        console.log(exc);
        return null;
    }
};

CodeBoot.prototype.verifyString = function (str, sig) {

    var algorithm = CodeBoot.prototype.signAlgorithm;
    var pubkeys = CodeBoot.prototype.setupKeys(CodeBoot.prototype.pubkeys);
    var hexsig = b64utohex(sig);

    for (var i=0; i<pubkeys.length; i++) {

        var key = pubkeys[i];

        try {
            var signature = new KJUR.crypto.Signature({ 'alg': algorithm });
            signature.init(key);
            signature.updateString(str);
            if (signature.verify(hexsig)) return true;
        } catch (exc) {
        }
    }

    return false;
};

