CodeBootVM.prototype.translateTEnum = function (lang, tenum) {
  var vm = this;

  var elements = tenum.elements

  var formatted_elements = [];

  for (let i = 0; i < elements.length; i ++) {
    var s = elements[i];
    if (typeof s == "string") {
      formatted_elements.push(s)
    } else if (s instanceof TFormat) {
      // TFormat
      formatted_elements.push(vm.translateTFormat(lang, s))
    } else {
      // TEnum
      formatted_elements.push(vm.translateTEnum(lang, s))
    }
  }

  switch (lang) {
    case "fr":
      // 1 item: "chien"
      // 2 items "chien et chat"
      // 2+ items "chien, chat et souris"
      return formatted_elements.slice(0, -2).concat(formatted_elements.slice(-2).join(" et ")).join(", ");

    case "en":
    default:
      // 1 item: "dog"
      // 2 items "dog and cat"
      // 2+ items "dog, cat, and mouse"
      if (formatted_elements.length > 2) {
        return formatted_elements.slice(0, -2).concat(formatted_elements.slice(-2).join(", and ")).join(", ");
      } else {
        return formatted_elements.join(" and ");
      }
  }
}

CodeBootVM.prototype.translateTFormat = function (lang, tformat) {
  var vm = this;

  var fields = tformat.fields;
  var template = tformat.template;

  var formatted_fields = [];

  for (let i = 0; i < fields.length; i ++) {
    var s = fields[i];
    if (typeof s === "string") {
      formatted_fields.push(s)
    } else if (s instanceof TFormat) {
      // TFormat
      formatted_fields.push(vm.translateTFormat(lang, s));
    } else {
      // TEnum
      formatted_fields.push(vm.translateTEnum(lang, s));
    }
  }

  return vm.format(vm.translate(lang, template), formatted_fields);
}

CodeBootVM.prototype.translateToCurrentLang = function (str) {

    var vm = this;

    return vm.translate(vm.getLanguage(), str);
};

CodeBootVM.prototype.translate = function (lang, str) {

    var vm = this;

    if (typeof str === "string") {

      var cbTranslateDict = vm.translateDict;
      var langTranslateDict = vm.lang.translateDict || {};

      var translation = cbTranslateDict[str] || langTranslateDict[str];

      if (translation !== void 0) {
          translation = translation[lang];
          if (translation !== void 0) {
              return translation;
          }
      }

      if (lang && lang !== "en") console.warn("no translation found", lang, str);

      return str;
    } else if (s instanceof TFormat) {
      // TFormat
      return vm.translateTFormat(lang, s);
    } else {
      // TEnum
      return vm.translateTEnum(lang, str);
    }
};

CodeBootVM.prototype.polyglotHTML = function (str, args) {
  var vm = this;

  if (!args) args = [];

  return vm.polyglotHTML_from_tformat(new TFormat(str, args));
};

CodeBootVM.prototype.polyglotHTML_from_tformat = function (tformat) {
  var vm = this;
  var HTML = '';

  for (var i=0; i<vm.langsUI.length; i++) {
      var lang = vm.langsUI[i][0];

      HTML += '<span class="cb-' + lang + '">' +
//              CodeBoot.prototype.escapeHTML(vm.translateTFormat(lang, tformat)) +
              vm.translateTFormat(lang, tformat) +
              '</span>';
  }

  return HTML;
};

CodeBootVM.prototype.format = function format(str, args) {
  var result = '';
  var i = 0;

  while (i < str.length) {
      var c = str[i++];
      if (c !== '{') {
          result += c;
      } else {
          var j = i;
          while (j < str.length) {
              c = str[j];
              if (!(c >= '0' && c <= '9')) break;
              j++;
          }
          var n = (j === i) ? 0 : parseInt(str.slice(i, j));
          i = j;
          if (i < str.length && c == '}') {
              result += args[n];
              i++;
          }
      }
  }
  return result;
}

CodeBootVM.prototype.setUILanguageFromBrowser = function () {

    var vm = this;

    var languages = navigator.languages.slice();
    var language = null;

    var elem = document.getElementsByTagName('html')[0];

    if (elem) {
        var lang = elem.getAttribute('lang');
        if (lang) {
            languages.unshift(lang);
        }
    }

    for (var i=vm.langsUI.length-1; i>=0; i--) {
        var langUI = vm.langsUI[i][0];
        for (var j=0; j<languages.length; j++) {
            if (langUI === languages[j]) {
                language = langUI;
                break;
            }
        }
    }

    if (language === null) {
        for (var i=vm.langsUI.length-1; i>=0; i--) {
            var langUI = vm.langsUI[i][0];
            for (var j=0; j<languages.length; j++) {
                if (languages[j].indexOf(langUI+'-') === 0) {
                    language = langUI;
                    break;
                }
            }
        }
    }

    if (language === null) {
        language = 'en';
    }

    vm.setLanguage(language);
};

function TFormat(template, fields) {
  var tformat = this;

  tformat.template = template;
  tformat.fields = fields || [];
}

TFormat.prototype.format = function() {
  var fields = this.fields;
  var formatted_fields = [];

  for (let i = 0; i < fields.length; i ++) {
    var s = fields[i];
    if (typeof s == "string") {
      formatted_fields.push(s)
    } else {
      // can be TFormat or TEnum, or other object with the format interface
      formatted_fields.push(s.format())
    }
  }

  return CodeBootVM.prototype.format(this.template, formatted_fields);
}

function TEnum(elements) {
  var tenum = this

  tenum.elements = elements
}

TEnum.prototype.format = function() {
  var tenum = this
  var elements = tenum.elements

  var formatted_elements = [];

  for (let i = 0; i < elements.length; i ++) {
    var s = elements[i];
    if (typeof s == "string") {
      formatted_elements.push(s)
    } else {
      // object with the format interface
      formatted_elements.push(s.format())
    }
  }
  // 1 item: "dog"
  // 2 items "dog and cat"
  // 2+ items "dog, cat, and mouse"
  if (formatted_elements.length > 2) {
    return formatted_elements.slice(0, -2).concat(formatted_elements.slice(-2).join(", and ")).join(", ");
  } else {
    return formatted_elements.join(" and ");
  }
}

function runtime_tformat(template, fields){
  return new TFormat(template, fields);
}

function runtime_tenum(elements){
  return new TEnum(elements);
}

function runtime_get_unique_translation_key(rte, translations) {
    var lang_dict = rte.vm.lang.translateDict;
    var global_dict = rte.vm.translateDict;

    function eqTrans(t1, t2) {
        if (!t1 || !t2) { return false };

        if (Object.keys(t1).length !== Object.keys(t2).length) { return false }

        for (let [key, value] of Object.entries(t1)) {
            if (t2[key] !== value) { return false };
        }

        return true;
    }

    function collision(key) {
        // There is a collision if the key already exists in one of the translation tables
        // AND the translation being added differs from the existing one. This prevents adding the same
        // translation multiple times for common sentences such as '{0} requires type {1}'.
        if (lang_dict.hasOwnProperty(key) && !eqTrans(lang_dict[key], translations)) {
            return true;
        }

        if (global_dict.hasOwnProperty(key) && !eqTrans(global_dict[key], translations)) {
            return true;
        }

        return false
    }

    // Default key is the english version of the text or first language available
    var key_base = translations["en"] || Object.values(translations)[0];

    if (key_base === undefined) {
        throw new Error("missing language")
    }

    var key = key_base;
    var count = 0;

    while (collision(key)) {
        key = key_base + count;
        count++;
    }

    return key;
}

function runtime_add_translation(rte, translations) {
    var translation_table = rte.vm.lang.translateDict;
    var available_lang = rte.vm.langsUI.map(x => x[0]);

    var filtered_translations = Object.keys(translations)
        // Remove any key which is not a known language
        .filter(lang => available_lang.includes(lang))
        .reduce((trans, lang) => {
            trans[lang] = translations[lang];
            return trans;
        }, {});

    var key = runtime_get_unique_translation_key(rte, filtered_translations);
    translation_table[key] = filtered_translations;

    // return a unique key that points to this translation
    return key
}

function dom_create_canvas(cls, width, height) {
    var c = document.createElement('canvas');
    c.className = cls;
    c.width = width;
    c.height = height;
//    c.style.border = '2px solid #eef';
//    c.style.padding = '1px';
    var ctx = dom_canvas_context(c);
    ctx.lineCap = 'butt';
    ctx.font = '10px Courier';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    return c;
}

function dom_create_canvas_cartesian(cls, width, height) {
    var c = dom_create_canvas(cls, width, height);
    var ctx = dom_canvas_context(c);
    ctx.translate(width/2, height/2);
    ctx.scale(1, -1);
    return c;
}

function dom_set_rotation(context, angle) {
  context.rotate(angle);
}

function dom_reset_transform(context, x, y) {
    context.setTransform(1, 0, 0, 1, x, y);
}

function dom_set_translation(context, x, y) {
    context.translate(x, y);
}

function dom_canvas_context(canvas) {
    var ctx = canvas.getContext('2d', { willReadFrequently: true });
    ctx.mozImageSmoothingEnabled = false;
    ctx.webkitImageSmoothingEnabled = false;
    ctx.msImageSmoothingEnabled = false;
    ctx.imageSmoothingEnabled = false;
    return ctx;
}

function dom_save(context) {
    context.save();
}

function dom_restore(context) {
    context.restore();
}

function dom_line_to(context, x0, y0, x1, y1) {
    context.beginPath();
    context.moveTo(x0, y0);
    context.lineTo(x1, y1);
    context.stroke();
}

function dom_fill_rect(context, x, y, w, h, color) {
    context.fillStyle = color;
    context.fillRect(x, y, w, h);
}

function dom_get_pixel(context, x, y) {
    var canvas = context.canvas;
    if (canvas) {
        var data = context.getImageData(x, y, 1, 1).data;
        return { r: data[0], g: data[1], b: data[2], a: data[3] };
    } else {
        return { r: 0, g: 0, b: 0, a: 0 };
    }
}

function dom_set_color(context, color) {
    context.strokeStyle = color;
}

function dom_set_thickness(context, thickness) {
    context.lineWidth = thickness;
}

function dom_clear(canvas) {
    var ctx = dom_canvas_context(canvas);
    ctx.clearRect(-canvas.width, -canvas.height, 2 * canvas.width, 2 * canvas.height);
}

function dom_canvas_width(canvas) {
    return canvas.width;
}

function dom_canvas_height(canvas) {
    return canvas.height;
}

function dom_set_font(context, font) {
    context.font = font;
}

function dom_set_text_baseline(context, baseline) {
    context.textBaseline = baseline;
}

function dom_set_text_align(context, align) {
    context.textAlign = align;
}

function dom_fill_text(context, text, x, y) {
    context.fillText(text, x, y);
}

function dom_measure_text(context, text) {
    var box = context.measureText(text);
    return [box.width, box.height];
}

function dom_remove_children(parent) {
    while (parent.hasChildNodes()) {
        parent.removeChild(parent.firstChild);
    }
}

function DrawingWindow(vm, width, height, scale) {

    var dw = this;

    dw.vm = vm;
    dw.width = width;
    dw.height = height;
    dw.scale = scale;

    dw.turtle_canvas = dom_create_canvas_cartesian('cb-turtle', width, height);
    dw.turtle_context = dom_canvas_context(dw.turtle_canvas);

    dw.drawing_canvas = dom_create_canvas_cartesian('cb-drawing', width, height);
    dw.drawing_context = dom_canvas_context(dw.drawing_canvas);

    dw.grid_canvas = dom_create_canvas_cartesian('cb-grid', width, height);
    dw.grid_context = dom_canvas_context(dw.grid_canvas);

    dom_set_color(dw.grid_context, '#eef');

    var w2 = width/2;
    var h2 = height/2;
    var grid_step = 10;

    for (var x=0; x<=w2; x+=grid_step) {
        var i = (x/grid_step)%10;
        dom_set_thickness(dw.grid_context, (i===0 ? 1.5 : i===5 ? 0.8 : 0.5));
        dom_line_to(dw.grid_context, x, -h2, x, h2);
        if (x>0)
            dom_line_to(dw.grid_context, -x, -h2, -x, h2);
    }

    for (var y=0; y<=h2; y+=grid_step) {
        var i = (y/grid_step)%10;
        dom_set_thickness(dw.grid_context, (i===0 ? 1.5 : i===5 ? 0.8 : 0.5));
        dom_line_to(dw.grid_context, -w2, y, w2, y);
        if (y>0)
            dom_line_to(dw.grid_context, -w2, -y, w2, -y);
    }

    dw.init();

    drawing_window = dw;//TODO: remove
}

DrawingWindow.prototype.min_width = 50;
DrawingWindow.prototype.max_width = 800;
DrawingWindow.prototype.min_height = 50;
DrawingWindow.prototype.max_height = 600;

var drawing_window;

DrawingWindow.prototype.toDataURL = function (noDecoration, noBackground) {

    var dw = this;
    var w = dw.drawing_canvas.width;
    var h = dw.drawing_canvas.height;
    var c = document.createElement('canvas');
    c.width = w;
    c.height = h;
    var ctx = dom_canvas_context(c);

    if (!noBackground) {
        ctx.fillStyle = 'rgba(255,255,255,1)';
        ctx.fillRect(0,0,w,h);
    }

    if (!noDecoration) {
        ctx.drawImage(dw.grid_canvas, 0, 0);
    }

    ctx.drawImage(dw.drawing_canvas, 0, 0);

    if (!noDecoration) {
        ctx.drawImage(dw.turtle_canvas, 0, 0);
    }

    return c.toDataURL();
};

DrawingWindow.prototype.screenshot = function (event) {
    var dw = this;
    var dataURL = dw.toDataURL(event.shiftKey, event.altKey);
    openDataURL(dataURL);
};

function openDataURL(dataURL){
    var win = window.open();
    win.document.write('<iframe src="' + dataURL  +'" frameborder="0" style="border:0; width:100%; height:100%;"></iframe>');
}

DrawingWindow.prototype.excursion = function (thunk) {
    var dw = this;
    var result;
    var pos = dw.pos;
    var scale = dw.scale;
    var thickness = dw.thickness;
    var orientation = dw.orientation;
    dom_save(dw.drawing_context);
    dw.turtle_height++;
    result = thunk();
    dom_restore(dw.drawing_context);
    --dw.turtle_height;
    dw.orientation = orientation;
    dw.thickness = thickness;
    dw.scale = scale;
    dw.pos = pos;
    return result;
};

DrawingWindow.prototype.init = function () {
    var dw = this;
    dom_clear(dw.drawing_canvas);
    dw.turtle_height = 0;
    dw.pen_height = 0;
    dw.move_mode = -1; // -1 = skip mv only, 1 = skip all, 0 = skip none
    dw.orientation = 0;
    dw.pos = { x:0, y:0 };
    dw.turtle_visible = false;
    dw.update_turtle_visibility(true);
    dw.set_color('#000');
    dw.set_thickness(0);
};

DrawingWindow.prototype.cs = function () {
    var dw = this;
    dw.init();
};

DrawingWindow.prototype.fd = function (xdistance, ydistance) {
    var dw = this;
    if (ydistance === void 0) ydistance = 0;
    var rad = Math.PI * (dw.orientation / 180);
    var x1 = xdistance * Math.cos(rad) - ydistance * Math.sin(rad);
    var y1 = xdistance * Math.sin(rad) + ydistance * Math.cos(rad);
    dw.mv(x1, y1, true);
};

DrawingWindow.prototype.bk = function (xdistance, ydistance) {
    var dw = this;
    if (ydistance === void 0) ydistance = 0;
    dw.fd(-xdistance,-ydistance);
};

DrawingWindow.prototype.mv = function (x, y, relative) {
    var dw = this;
    var x0 = dw.pos.x;
    var y0 = dw.pos.y;
    var x1 = dw.scale * x;
    var y1 = dw.scale * y;
    if (relative) {
        x1 += x0;
        y1 += y0;
    }
    if ((relative ? dw.move_mode !== 1 : dw.move_mode === 0) &&
        dw.pen_height === 0) {
        dom_line_to(dw.drawing_context, x0, y0, x1, y1);
    }
    dw.update_turtle_visibility(false);
    dw.pos = { x:x1, y:y1 };
    dw.update_turtle_visibility(!!relative);
    dw.move_mode = 0;
};

DrawingWindow.prototype.set_color = function (color) {
    var dw = this;
    dom_set_color(dw.drawing_context, color);
};

DrawingWindow.prototype.set_thickness = function (thickness) {
    var dw = this;
    var ctx = dw.drawing_context;
    var s = Math.abs(dw.scale);
    var t = (thickness <= 0) ? 1 : s*thickness;
    dw.thickness = thickness;
    dom_set_font(ctx, ((thickness <= 0) ? 10 : s*(9+t)) + 'px Courier');
    dom_set_thickness(ctx, t);
};

DrawingWindow.prototype.pd = function () {
    var dw = this;
    if (--dw.pen_height <= 0) {
        dw.pen_height = 0;
    }
};

DrawingWindow.prototype.pu = function () {
    var dw = this;
    dw.pen_height++;
};

DrawingWindow.prototype.hop = function () {
    var dw = this;
    dw.move_mode = 1;
};

DrawingWindow.prototype.triangle = function (h, base) {
    var dw = this;
    var x = base/2;
    var y = Math.sqrt(x*x + h*h);
    var alpha = 180 * Math.asin(h/y) / Math.PI;
    var beta = 2 * (90 - alpha);
    dw.lt(90);
    dw.pu(); dw.fd(x); dw.pd();
    dw.rt(180 - alpha);
    dw.fd(y);
    dw.rt(180 - beta);
    dw.fd(y);
    dw.rt(180 - alpha);
    dw.fd(2*x);
};

DrawingWindow.prototype.draw_turtle = function () {
    var dw = this;
    dw.excursion(function () {
        var save_canvas = dw.drawing_canvas;
        var save_context = dw.drawing_context;
        var save_pen = dw.pen_height;
        var save_move_mode = dw.move_mode;
        var save_turtle_visible = dw.turtle_visible;
        dw.pen_height = 0;
        dw.move_mode = 0;
        dw.scale = 1;
        dw.drawing_canvas = dw.turtle_canvas;
        dw.drawing_context = dw.turtle_context;
        dom_clear(dw.drawing_canvas);
        dw.set_color('#f00');
        dw.set_thickness(2);
        dw.triangle(15, 10);
        dw.drawing_canvas = save_canvas;
        dw.drawing_context = save_context;
        dw.pen_height = save_pen;
        dw.move_mode = save_move_mode;
        dw.turtle_visible = save_turtle_visible;
    });
};

DrawingWindow.prototype.update_turtle_visibility = function (show) {
    var dw = this;
    var should_be_visible = (show && dw.turtle_height <= 0);
    if (dw.turtle_visible !== should_be_visible) {
        dw.turtle_visible = should_be_visible;
        if (should_be_visible) {
            dw.draw_turtle();
        } else {
            dom_clear(dw.turtle_canvas);
        }
    }
};

DrawingWindow.prototype.st = function () {
    var dw = this;
    dw.update_turtle_visibility(false);
    if (--dw.turtle_height < 0) dw.turtle_height = 0;
    dw.update_turtle_visibility(true);
};

DrawingWindow.prototype.ht = function () {
    var dw = this;
    dw.update_turtle_visibility(false);
    dw.turtle_height++;
    dw.update_turtle_visibility(true);
};

DrawingWindow.prototype.lt = function (angle) {
    var dw = this;
    dw.update_turtle_visibility(false);
    dw.orientation += angle;
    dw.update_turtle_visibility(true);
};

DrawingWindow.prototype.rt = function (angle) {
    var dw = this;
    dw.lt(-angle);
};

DrawingWindow.prototype.setpc = function (r, g, b) {
    var dw = this;
    var color = convertRGB4({r:Math.floor(r*15),g:Math.floor(g*15),b:Math.floor(b*15)});
    dw.set_color(color || blackRGB);
};

DrawingWindow.prototype.setpw = function (thickness) {
    var dw = this;
    dw.set_thickness(thickness);
};

DrawingWindow.prototype.setscale = function (scale) {
    var dw = this;
    dw.scale = scale;
    dw.set_thickness(dw.thickness);
};

DrawingWindow.prototype.drawtext = function (text) {
    var dw = this;
    var ctx = dw.drawing_context;
    ctx.save();
    ctx.translate(dw.pos.x, dw.pos.y);
    ctx.rotate(Math.PI*(dw.orientation/180));
    ctx.scale(1, -1);
    dom_fill_text(ctx, text+'', 0, 0);
    ctx.restore();
};

DrawingWindow.prototype.pageToRelative = function (coord, clamp) {
    var dw = this;
    var rect = getCoords(dw.drawing_canvas);
    var w = dw.drawing_canvas.width;
    var h = dw.drawing_canvas.height;
    var x = coord.x - rect.x - 3;
    var y = coord.y - rect.y - 3;
    if (clamp) {
        x = Math.max(0, Math.min(w, x));
        y = Math.max(0, Math.min(h, y));
    }
    return { x: x - w/2, y: h/2 - y };
};

function getCoords(elem) {
    var rect = elem.getBoundingClientRect();
    return { x: rect.left + pageXOffset, y: rect.top + pageYOffset };
}

DrawingWindow.prototype.prepareToShow = function () {

    var dw = this;
    var vm = dw.vm;

    vm.setPlaygroundToShow('drawing');
};

DrawingWindow.prototype.setShow = function (show) {

    var dw = this;
    var vm = dw.vm;

    vm.setCheckmark('data-cb-setting-playground', 'show-drawing-window', show);

    if (show) {
        $('.cb-html-window').css('display', 'none');
        $('.cb-pixels-window').css('display', 'none');
        $('.cb-drawing-window').css('display', 'inline');
        var parent = vm.root.querySelector('.cb-drawing-window');
        dom_remove_children(parent);
        parent.appendChild(drawing_window.grid_canvas);
        parent.appendChild(drawing_window.drawing_canvas);
        parent.appendChild(drawing_window.turtle_canvas);
    } else {
        var parent = vm.root.querySelector('.cb-drawing-window');
        dom_remove_children(parent);
        $('.cb-drawing-window').css('display', 'none');
    }
};

DrawingWindow.prototype.showing = function () {
    return $('.cb-drawing-window').is(':visible');
}

