CodeBootVM.prototype.undo = function (cm) {
    cm.undo();
};

CodeBootVM.prototype.redo = function (cm) {
    cm.redo();
};

CodeBootVM.prototype.initTextEditor = function (textEditor, cm, elem, history, file) {

    var vm = this;

    textEditor.cb = {};
    textEditor.cb.elem = elem;
    textEditor.cb.cm = cm;
    textEditor.cb.vm = vm;
    textEditor.cb.hm = history;
    textEditor.cb.file = file;
    textEditor.cb.transcriptMarker = null;
    vm.setTranscriptMarker(textEditor, vm.beginningOfEditor());

//    textEditor.on('paste', function(cm, event) {
//        vm.afterDelay(function () { textEditor.refresh(); });
//        //event.preventDefault();
//    });
};

CodeBootVM.prototype.setFocusREPL = function (repl) {

    var vm = this;

    vm.setAttribute('data-cb-focus-repl', repl);
};

CodeBootVM.prototype.trackTextEditorFocus = function (textEditor, focus) {

    var vm = this;

    if (focus) {
        if (!vm.isRunning()) {
            vm.lastFocusedEditor = textEditor;
            vm.setFocusREPL(textEditor.cb.cm === vm.repl);
        }
    } else if (!vm.allowLosingFocus) {
        vm.afterDelay(function () {
            vm.focusLastFocusedEditor();
        });
    }
};

CodeBootVM.prototype.initTextEditorFocusHandling = function (textEditor) {

    var vm = this;

    textEditor.cb.cm.on('focus', function (cm, event) {
        vm.trackTextEditorFocus(textEditor, true);
    });

    textEditor.cb.cm.on('blur', function (cm, event) {
        vm.trackTextEditorFocus(textEditor, false);
    });
};

CodeBootVM.prototype.initTextEditorScrollHandling = function (textEditor) {

    var vm = this;

    textEditor.cb.cm.on('scroll', function (cm) {
        vm.updatePopupPos();
    });

};

// Disable Ctrl-V and Ctrl-X keybindings that users expect to map to paste/cut
delete CodeMirror.keyMap.emacs['Ctrl-V'];
delete CodeMirror.keyMap.emacs['Ctrl-X'];

function CodeBootTextEditor(elem, file) {

    var te = this;
    var vm = file.fs.vm;

    function enter(cm) {
        if (!vm.isRunning()) {
            return CodeMirror.Pass;
        }
        vm.eventEval();
    };

    function shiftEnter(cm) {
        vm.eventStepPause();
    };

    var rulers = [{color: '#000', column: 79, lineStyle: 'dashed'}];

    function handler(h) {
        return function (cm) {
            if (vm.isHidden()) {
                return CodeMirror.Pass;
            } else {
                return h(cm);
            }
        };
    }

    var options = {
        value: file.content,
        lineNumbers: vm.showLineNumbers,
        cursorScrollMargin: 0,
//        scrollbarStyle: 'null', // avoid 2 scrollbars... why needed?
        gutters: ['CodeMirror-linenumbers', 'cb-file-cm-gutter'],
        fixedGutter: false,
        matchBrackets: true,
        rulers: rulers,
        keyMap: 'emacs',
        extraKeys: {

            //TODO: reenable
            //'Ctrl-/' : function (cm) {
            //    var tok = cm.getTokenAt(cm.getCursor(false));
            //    var isComment = tok.className === 'comment';
            //    cm.commentRange(!isComment, cm.getCursor(true), cm.getCursor(false));
            // },

            'Ctrl-L': handler(function (cm) { vm.eventClearConsole(); }),
            'Shift-Ctrl-/': handler(function (cm) { vm.toggleDevMode(); }),
            'Esc': handler(function (cm) { vm.eventStop(); }),
            'Enter': handler(enter),
            'Shift-Enter': handler(shiftEnter),
            'Shift-Ctrl-Enter': handler(function (cm) { vm.eventEval(); }),
            'F5' : handler(function (cm) { vm.eventStepPause(); }),
            'F6' : handler(function (cm) { vm.eventAnimate(); }),
            'F7' : handler(function (cm) { vm.eventEval(); }),
            'F8' : handler(function (cm) { vm.eventStop(); })
        },
        dragDrop: false,
        //,viewportMargin: Infinity
    };

    vm.adjustTextEditorOptions(options);

    var cm = CodeMirror.fromTextArea(elem, options);

    if (file.cursor) {
        cm.setCursor(file.cursor);
    }

    cm.on('change', function (cm) { vm.hideReasonHighlight(); });

    te.cm = cm;

//    vm.lang.setupEditor(cm);

    vm.initTextEditor(te, cm, elem, null, file);
    vm.initTextEditorFocusHandling(te);
    vm.initTextEditorScrollHandling(te);

    te.cm.getDoc().clearHistory();
}

CodeBootTextEditor.prototype.focus = function () {

    var te = this;

    te.cm.focus();
};

CodeBootTextEditor.prototype.refresh = function () {

    var te = this;

//    console.log('CodeBootTextEditor.prototype.refresh');

    te.cm.refresh();
};

CodeBootTextEditor.prototype.setOption = function (name, val) {

    var te = this;

//    console.log('CodeBootTextEditor.prototype.setOption');

    te.cm.setOption(name, val);
};

CodeBootTextEditor.prototype.setReadOnly = function (readOnly) {

    var te = this;

//    console.log('CodeBootTextEditor.prototype.setReadOnly('+readOnly+')');

    te.cm.setOption('readOnly', readOnly);
    te.cm.setOption('matchBrackets', !readOnly);
};

CodeBootTextEditor.prototype.getValue = function () {

    var te = this;

    val = te.cm.getValue();
//    console.log('CodeBootTextEditor.prototype.getValue');
//    console.log(val);
    return val;
    return te.cm.getValue();
};

CodeBootTextEditor.prototype.setValue = function (val) {

    var te = this;

//    console.log('CodeBootTextEditor.prototype.setValue');
//    console.log(val);

    te.cm.setValue(val);
    te.cm.getDoc().clearHistory();
};

CodeBootTextEditor.prototype.setCursor = function (cursor) {

    var te = this;

    te.cm.setCursor(cursor);
};

CodeBootTextEditor.prototype.toHTML = function (opts) {

    var te = this;

    return CodeBootVM.prototype.cmToHTML(te.cm, opts);
};

CodeBootVM.prototype.editFileFromRealFS = function (cm, path) {

    var vm = this;

    if (!cm) return;

    vm.readFileFromRealFSSync(path, function(contents) {
        cm.setValue(contents);
    });
};

CodeBootVM.prototype.readFileFromRealFSSync = function (path, callback) {

    var vm = this;

    if (typeof FileReader === 'undefined') {
        //TODO: add translation?
        vm.reportError('FileReader not supported by the browser');
        return;
    }

    var reader = new FileReader();
    reader.onerror = function (e) {
        vm.reportError('FileReader failed to read ' + path);
    };
    reader.onload = function(e) {
        callback(e.target.result);
    };
    reader.readAsText(path);
}

