CodeBootVM.prototype.setReadOnly = function (textEditor, val) {

    var vm = this;

    if (textEditor.cb.cm) {
        textEditor.cb.cm.setOption('readOnly', val);
        textEditor.cb.cm.setOption('matchBrackets', !val);
    }
};

CodeBootVM.prototype.adjustTextEditorOptions = function (options) {

    var vm = this;

    if (!vm.editable) {
        options.inputStyle = 'contenteditable';
        options.readOnly = 'nocursor';
    }
};

CodeBootVM.prototype.replSetup = function () {

    var vm = this;
    var node = vm.root.querySelector('.cb-repl');

    if (node && !vm.repl) {

        function cursorUp(cm) {
            if (cm.cb.vm.replCursorOnFirstLineOfInput()) {
                cm.cb.hm.previous();
            } else {
                cm.execCommand('goLineUp');
            }
        };

        function cursorDown(cm) {
            if (cm.cb.vm.replCursorOnLastLineOfInput()) {
                cm.cb.hm.next();
            } else {
                cm.execCommand('goLineDown');
            }
        };

        function insertLine(cm) {
            var first = vm.replCursorOnFirstLineOfInput();
            cm.cb.vm.replAddInputLine('', first, false);
            vm.replAddPrompt2(true); // add continuation prompt to new line
            cm.execCommand('goCharLeft');
        };

        function newline(cm) {
            var first = vm.replCursorOnFirstLineOfInput();
            cm.cb.vm.replAddInputLine('', first, false);
            vm.replAddPrompt2(true); // add continuation prompt to new line
        };

        function newlineAndIndent(cm) {
            var first = vm.replCursorOnFirstLineOfInput();
            cm.cb.vm.replAddInputLine('', first, false);
            vm.replAddPrompt2(true); // add continuation prompt to new line
            cm.execCommand('indentAuto');
        };

        function enter(cm) {
            if (true || cm.cb.vm.replCursorOnLastLineOfInput()) {
                cm.cb.vm.replSetCursorToEnd();
                cm.cb.vm.eventEval();
            } else {
                newlineAndIndent(cm);
            }
        };

        function shiftEnter(cm) {
            if (true || cm.cb.vm.replCursorOnLastLineOfInput()) {
                cm.cb.vm.replSetCursorToEnd();
                cm.cb.vm.eventStepPause();
            } else {
                newlineAndIndent(cm);
            }
        };

        function handler(h) {
            return function (cm) {
                if (cm.cb.vm.isHidden()) {
                    return CodeMirror.Pass;
                } else {
                    return h(cm);
                }
            };
        }

        var options = {
            lineNumbers: false,    // Show line numbers
            matchBrackets: true,
            keyMap: 'emacs',
            cursorScrollMargin: 0,
            gutters: ['CodeMirror-linenumbers', 'cb-repl-cm-gutter'],
            fixedGutter: false,
            extraKeys: {
                'Ctrl-L': handler(function (cm) { cm.cb.vm.eventClearConsole(); }),
                'Shift-Ctrl-/': handler(function (cm) { cm.cb.vm.toggleDevMode(); }),
                'Up': handler(cursorUp),
                'Ctrl-P': handler(cursorUp),
                'Down': handler(cursorDown),
                'Ctrl-N': handler(cursorDown),
                'Ctrl-J': handler(newline),
                'Ctrl-O': handler(insertLine),
                'Ctrl-R': handler(function (cm) { }),
                'Ctrl-S': handler(function (cm) { }),
                'Esc': handler(function (cm) { cm.cb.vm.eventStop(); }),
                'Enter': handler(enter),
                'Shift-Enter': handler(shiftEnter),
                'Shift-Ctrl-Enter': handler(function (cm) { cm.cb.vm.eventEval(); }),
                'F5' : handler(function (cm) { cm.cb.vm.eventStepPause(); }),
                'F6' : handler(function (cm) { cm.cb.vm.eventAnimate(); }),
                'F7' : handler(function (cm) { cm.cb.vm.eventEval(); }),
                'F8' : handler(function (cm) { cm.cb.vm.eventStop(); })
            },
            dragDrop: false,
            //viewportMargin: Infinity,
            lineWrapping: true
        };

        vm.adjustTextEditorOptions(options);

        var textEditor = CodeMirror.fromTextArea(node, options);

        textEditor.on('change', function (cm) { vm.hideReasonHighlight(); });

        vm.repl = textEditor;

        vm.initTextEditor(textEditor, textEditor, node, new CodeBootHistoryManager(textEditor), null);
        vm.initTextEditorFocusHandling(textEditor);
        vm.initTextEditorScrollHandling(textEditor);
    }

    if (vm.repl) {
        var width = vm.replPromptWidth();
        vm.forEachElem('.cb-console', function (elem) {
            elem.setAttribute('data-cb-prompt-width', width+'');
        });
        vm.lang.setupEditor(vm.repl);
        vm.replReset();
        vm.repl.refresh();
        vm.repl.focus();
    }
};

CodeBootVM.prototype.replPromptWidth = function () {

    var vm = this;

    return Math.max(vm.lang.getPrompt().length,
                    vm.lang.getPromptCont().length);
};

CodeBootVM.prototype.replCursorOnFirstColumnOfInput = function () {

    var vm = this;
    var textEditor = vm.repl;

    return textEditor.cb.cm.getCursor().ch === 0;
};

CodeBootVM.prototype.replCursorOnFirstLineOfInput = function () {

    var vm = this;
    var textEditor = vm.repl;

    var cursor = textEditor.cb.cm.cursorCoords(textEditor.cb.cm.getCursor());
    var first = textEditor.cb.cm.cursorCoords(vm.replInputPos());

    return cursor.top === first.top;
};

CodeBootVM.prototype.replCursorOnLastLineOfInput = function () {

    var vm = this;
    var textEditor = vm.repl;

    var cursor = textEditor.cb.cm.cursorCoords(textEditor.cb.cm.getCursor());
    var last = textEditor.cb.cm.cursorCoords({ line: textEditor.cb.cm.lastLine()+1, ch: 0 });

    return cursor.top === last.top;
};

CodeBootVM.prototype.replCursorPos = function () {

    var vm = this;
    var textEditor = vm.repl;

    return textEditor.cb.cm.getCursor();
};

CodeBootVM.prototype.replNewline = function () {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replNewline');
    if (!textEditor) return;

    var first = vm.replCursorOnFirstLineOfInput();
    vm.replAddInputLine('', first, false);
    textEditor.cb.cm.execCommand('indentAuto');
};

CodeBootVM.prototype.replAcceptInput = function () {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replAcceptInput |'+vm.replGetInput()+'|');
    if (!textEditor) return;
/*
    var input = vm.replGetInput();
    var nl = input.lastIndexOf('\n');

    // avoid empty lines that prevent prompt from showing
    if (nl === input.length-1)
        textEditor.cb.cm.replaceRange('\f', vm.endOfEditor(), vm.endOfEditor());

    vm.replAddPrompt2(nl >= 0); // set prompt of last line of input

    textEditor.cb.cm.replaceRange('\n', vm.endOfEditor(), vm.endOfEditor());
*/
    vm.replAddInputLine('',
                        vm.replCursorOnFirstLineOfInput(),
                        false);

//    vm.replAddPrompt2(false); // add normal prompt

    vm.replSetReadOnlyTranscript(vm.endOfEditor());

    vm.replScrollToEnd();
};

CodeBootVM.prototype.replInputPos = function () {

    var vm = this;
    var textEditor = vm.repl;

    var transcriptPos = textEditor.cb.transcriptMarker.find();
    return transcriptPos ? transcriptPos.to : vm.beginningOfEditor();
};

CodeBootVM.prototype.replInputEndPos = function () {

    var vm = this;
    var textEditor = vm.repl;

    return vm.offsetFromEndOfEditor(textEditor, 0);
};

CodeBootVM.prototype.replEmptyInput = function () {

    var vm = this;
    var textEditor = vm.repl;

    if (!textEditor) return true;

    var start = vm.replInputPos();
    var cursor = textEditor.cb.cm.getCursor();
    return start.line === cursor.line;
};

CodeBootVM.prototype.replGetTranscript = function () {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replGetTranscript');
//    return textEditor.cb.cm.getRange(vm.beginningOfEditor(), vm.endOfEditor());
    return textEditor.cb.cm.display.wrapper.innerText;
};

CodeBootVM.prototype.replGetHistorySinceReset = function (includeInput) {

    var vm = this;
    var textEditor = vm.repl;

    var history = vm.repl.cb.hm.getHistorySinceResetREPL();

    if (includeInput) {

        var input = vm.replGetInput();

        if (input.length > 0 || history.length > 0) {
            history += '\n';
        }

        return history + input;
    } else {
        return history;
    }
};

CodeBootVM.prototype.replGetInput = function () {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replGetInput');
    return textEditor.cb.cm.getRange(vm.replInputPos(), vm.endOfEditor());
};

CodeBootVM.prototype.replSetCursorToEnd = function () {

    var vm = this;
    var textEditor = vm.repl;

    textEditor.cb.cm.setCursor(vm.endOfEditor());
    vm.replScrollToEnd();
//    console.log('did replSetCursorToEnd();');
};

CodeBootVM.prototype.replSetInput = function (text, startPos) {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replSetInput');
    if (!textEditor) return;

    var lines = text.split('\n');

    if (!startPos) {
        startPos = vm.replInputPos();
    }

    textEditor.cb.cm.replaceRange('', startPos, vm.endOfEditor());

    for (var i=0; i<lines.length; i++) {
        vm.replAddInputLine(lines[i], i === 0, i === lines.length-1);
    }

    vm.replSetCursorToEnd();
//    textEditor.cb.cm.setCursor(vm.endOfEditor());

//TODO: deprecated
//    cm.setValue(text);
//    cm.setCursor(0, text.length);
};

CodeBootVM.prototype.replAddInputLine = function (line, first, last) {

    var vm = this;
    var textEditor = vm.repl;

    var addSpace = (line === '' && !last);
    if (addSpace) line += ' '; // on empty line: add then remove space
                               // to avoid hidden gutter bug
    textEditor.cb.cm.replaceRange(line,
                                  textEditor.cb.cm.getCursor(),
                                  textEditor.cb.cm.getCursor());
    vm.replAddPrompt2(!first); // normal or continuation prompt
    if (!last) {
        textEditor.cb.cm.replaceRange('\n',
                                      vm.getOffsetFromCursor(textEditor,addSpace?-1:0),
                                      textEditor.cb.cm.getCursor());
    }
};

/*deprecated

CodeBootVM.prototype.replReplaceInput = function (text) {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replReplaceInput');
    if (!textEditor) return;

    var lines = text.split('\n');
    textEditor.cb.cm.replaceRange(text, vm.replInputPos(), vm.endOfEditor());
};
*/

CodeBootVM.prototype.replReset = function () {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replReset');
    if (!textEditor) return;

    textEditor.cb.cm.setValue('');
    vm.setTranscriptMarker(textEditor, vm.beginningOfEditor());
    vm.lastSourceStartPos = null;
    vm.lastSourceEndPos = null;
    vm.replAllowInput();
    vm.repl.cb.hm.resetPos();
    vm.repl.cb.hm.resetREPL();
};

CodeBootVM.prototype.setTranscriptMarker = function (textEditor, endPos) {

    var vm = this;

    if (textEditor.cb.transcriptMarker) {
        textEditor.cb.transcriptMarker.clear();
        textEditor.cb.transcriptMarker = null;
    }

    textEditor.cb.transcriptMarker =
        textEditor.cb.cm.markText(
            vm.beginningOfEditor(),
            endPos,
            { className: 'cb-transcript',
              inclusiveLeft: true,
              //atomic: true,
              readOnly: true } );
};

CodeBootVM.prototype.replSetReadOnlyTranscript = function (endPos) {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replSetReadOnlyTranscript');
    if (!textEditor) return;

    vm.setTranscriptMarker(textEditor, endPos);
};

CodeBootVM.prototype.replAllowInput = function () {

    var vm = this;

    vm.replAddPrompt2(!vm.replEmptyInput());
};

CodeBootVM.prototype.replAddPrompt = function () {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replAddPrompt');
    if (!textEditor) return;

//    if (text !== undefined)
//        vm.replSetInput(text);

    var line = textEditor.cb.cm.lastLine();

    var prompt = !vm.replEmptyInput()
                 ? vm.lang.getPromptCont()
                 : vm.lang.getPrompt();
    var elem = document.createElement('div');
    elem.innerText = prompt;
    textEditor.cb.cm.setGutterMarker(line, 'cb-repl-cm-gutter', elem);

    vm.replSetCursorToEnd();
};

CodeBootVM.prototype.replAddPrompt2 = function (cont) {

    var vm = this;
    var textEditor = vm.repl;

//    console.log('replAddPrompt2');
    if (!textEditor) return;

    var cursor = vm.replCursorPos();
    var prompt = cont
                 ? vm.lang.getPromptCont()
                 : vm.lang.getPrompt();
    var elem = document.createElement('div');
    elem.innerText = prompt;
    textEditor.cb.cm.setGutterMarker(cursor.line, 'cb-repl-cm-gutter', elem);
    textEditor.cb.cm.refresh();
};

CodeBootVM.prototype.scrollToEnd = function (textEditor) {
    var vm = this;
    CodeMirror.commands.goDocEnd(textEditor.cb.cm);
};

CodeBootVM.prototype.replScrollToEnd = function () {
    var vm = this;
    var textEditor = vm.repl;
    vm.scrollToEnd(textEditor);
};

CodeBootVM.prototype.nextLineStart = function (pos, nbLines) {
    if (nbLines === undefined) nbLines = 1;
    return { line: pos.line+nbLines, ch: 0 };
};

CodeBootVM.prototype.beginningOfEditor = function () {
    return { line: 0, ch: 0 };
};

CodeBootVM.prototype.beginningOfLastLineOfEditor = function (textEditor) {
    return { line: textEditor.cb.cm.lastLine(), ch: 0 };
};

CodeBootVM.prototype.offsetFromEndOfEditor = function (textEditor, offset) {
    var pos = textEditor.cb.cm.posFromIndex(Infinity); // get end line/ch
    if (offset === 0) return pos;
    var ind = textEditor.cb.cm.indexFromPos(pos); // get actual index
    return textEditor.cb.cm.posFromIndex(ind + offset);
};

CodeBootVM.prototype.getOffsetFromCursor = function (textEditor, offset) {
    var pos = textEditor.cb.cm.getCursor(); // get end line/ch
    if (offset === 0) return pos;
    var ind = textEditor.cb.cm.indexFromPos(pos); // get actual index
    return textEditor.cb.cm.posFromIndex(ind + offset);
};

CodeBootVM.prototype.endOfEditor = function () {
    return { line: Infinity, ch: 0 };
};

