CodeBootVM.prototype.replAddLineWidgetTranscript = function (widget) {

    var vm = this;
    var textEditor = vm.repl;

    if (!textEditor) return;
//    console.log('starting vm.replAddLineWidgetTranscript');

    var pos = vm.replInputPos();
    var w = textEditor.cb.cm.addLineWidget(pos.line-1, widget);
//    var w = textEditor.cb.cm.addWidget(vm.lastLinePos(vm.repl), widget, false);
//    var w = textEditor.cb.cm.addLineWidget(textEditor.cb.cm.lineCount() - 2, widget);

    vm.replScrollToEnd();
};

CodeBootVM.prototype.replAddTranscript = function (text, cssClass) {

    var vm = this;
    var textEditor = vm.repl;

    if (!textEditor) return;

    text = text.split('\r').join(''); // remove carriage-return

    if (text.length > 0) {

        if (text[text.length-1] !== '\n') text += '\n';

        var start_pos = vm.replInputPos();

        textEditor.cb.cm.replaceRange(text, start_pos);

        var end_pos = vm.nextLineStart(start_pos, text.split('\n').length - 1);

        textEditor.cb.cm.markText(start_pos, end_pos, { className: cssClass });

        vm.replSetReadOnlyTranscript(end_pos);

        vm.replScrollToEnd();

        vm.setAttribute('data-cb-show-console', true);
        vm.setAttribute('data-cb-show-repl-container', true);
        vm.setHidden(false);
    }
};

/* ----- UI helpers ----- */

CodeBootVM.prototype.scrollTo = function (elementOrSelector) {
    var elementOffset = $(elementOrSelector).position().top;
    $('.cb-editors').animate({scrollTop: elementOffset}, 400);
};

/* ----- Internal file system ----- */

var BUILTIN_FILES = {

    'sample/hello.js' :
        '// This program prints a famous greeting\n' +
        '\n' +
        'print("Hello, world!");\n',

    'sample/hello.py' :
        '# This program prints a famous greeting\n' +
        '\n' +
        'print("Hello, world!")\n',

    'sample/sqrt2.js' :
        '// This program computes the square root of 2 without using Math.sqrt\n' +
        '\n' +
        'var n = 2;       // number whose square root is to be computed\n' +
        'var approx = n;  // first approximation of sqrt(n)\n' +
        '\n' +
        'for (;;) {\n' +
        '    next = (approx + n/approx) / 2;  // improve approximation\n' +
        '    if (next == approx)              // stop when no improvement\n' +
        '        break;\n' +
        '}\n' +
        '\n' +
        'print(approx);  // print square root of n\n',

    'sample/sqrt2.py' :
        '# This program computes the square root of 2 without using math.sqrt\n' +
        '\n' +
        'n = 2       # number whose square root is to be computed\n' +
        'approx = n  # first approximation of sqrt(n)\n' +
        '\n' +
        'while True:\n' +
        '    next = (approx + n/approx) / 2  # improve approximation\n' +
        '    if next == approx:              # stop when no improvement\n' +
        '        break\n' +
        '    approx = next\n' +
        '\n' +
        'print(approx)  # print square root of n\n'
};

BUILTIN_FILES = {};
NEW_FILE_DEFAULT_CONTENT = '';

function CodeBootFile(fs, filename, content, opts) {

    var file = this;
    var vm = fs.vm;

    file.fs = fs;
    file.filename = filename;
    file.content = (content !== undefined) ? content : NEW_FILE_DEFAULT_CONTENT;
    file.cursor = null;
    file.stamp = 0;
    file.preferredEditorView = null;

    new CodeBootFileEditor(file); // initializes file.fe

    if (opts) {
        for (var prop in opts) {
            file[prop] = opts[prop];
        }
    }
}

CodeBootFile.prototype.extension = function (filename) {

    var dot = filename.lastIndexOf('.');
    var slash = filename.lastIndexOf('/');

    if (dot > slash)
        return filename.slice(dot);
    else
        return '';
};

CodeBootFile.prototype.stripExtension = function (filename) {

    var dot = filename.lastIndexOf('.');
    var slash = filename.lastIndexOf('/');

    if (dot > slash)
        return filename.slice(0, dot);
    else
        return filename;
};

CodeBootFile.prototype.stripDirectory = function (filename) {

    var slash = filename.lastIndexOf('/');

    return filename.slice(slash+1);
};

CodeBootFile.prototype.stripDirectoryAndExtension = function (filename) {

    return CodeBootFile.prototype.stripExtension(CodeBootFile.prototype.stripDirectory(filename));
};

CodeBootFile.prototype.getExtension = function () {

    var file = this;

    return file.extension(file.filename);
};

CodeBootFile.prototype.getContent = function () {

    var file = this;

    var content = file.content;

    if (file.fe.isEnabled()) {
        content = file.fe.getValue();
    }

    return content;
};

CodeBootFile.prototype.setContent = function (content) {

    var file = this;

    file.content = content;
    file.fe.setValue(content);
};

CodeBootFile.prototype.save = function () {

    var file = this;

    if (file.fe.isEnabled()) {
        var oldContent = file.content;
        var newContent = file.fe.getValue();
        if (newContent !== oldContent) {
            file.content = newContent;
            file.stamp += 1;
        }
    }
};

CodeBootFile.prototype.serialize = function () {

    var file = this;

    var json = {
        filename: file.filename,
        content: file.getContent(),
        cursor: file.cursor === null ?
                {line: 0, ch: 0} :
                {line: file.cursor.line, ch: file.cursor.ch},
        stamp: file.stamp,
        preferredEditorView: file.preferredEditorView
    };

    return json;
};

CodeBootFile.prototype.clone = function () {

    var file = this;
    var other = new CodeBootFile(file.fs, file.filename, file.content);

    for (var prop in file) {
        if (Object.prototype.hasOwnProperty.call(file, prop)) {
            other[prop] = file[prop];
        }
    }

    return other;
};

CodeBootFile.prototype.setReadOnly = function (readOnly) {

    var file = this;

    file.fe.setReadOnly(readOnly);
};

CodeBootFile.prototype.toURL = function (isolated, type) {

    var file = this;

//TODO: deprecated?
//    if (!file.fs.vm.allowURLCreation()) return null;

    return file.fs.vm.commandsToURL([file.toCommand(type)], isolated);
};

CodeBootFile.prototype.defaultType = function () {

    var file = this;
    var fe = file.fe;
    var type = null;

    if (fe.isEnabled()) {
        var activated = fe.isActivated();
        var launch = fe.isLaunch();
        type = { activated: activated, launch: launch };
    }

    return type;
};

CodeBootFile.prototype.toCommand = function (type) {

    var file = this;

    if (type === undefined) {
        type = file.defaultType();
    }

    return CodeBoot.prototype.fileToCommand(type,
                                            file.filename,
                                            file.getContent())
};

function CodeBootFileSystem(vm) {

    var fs = this;

    fs.vm = vm;

    new CodeBootFileEditorManager(fs); // initializes fs.fem

    vm.fs = fs;
}

CodeBootFileSystem.prototype.init = function () {

    var fs = this;

    fs.removeFileEditors();
    fs.initFileTabs();
    fs.clear();
    fs.initFileMenu();
};

CodeBootFileSystem.prototype.initFileTabs = function () {

    var fs = this;
    var vm = fs.vm;

    vm.withElem('.cb-file-tabs', function (tabsElem) {
        var sentinelTab = document.createElement('li');
        sentinelTab.className = 'cb-file-tab';
        sentinelTab.innerHTML = '<div class="cb-tab-spacer"></div>';
        tabsElem.innerHTML = '';
        tabsElem.appendChild(sentinelTab);
        fs.setupTabDragAndDrop(sentinelTab, null);
    });
};

CodeBootFileSystem.prototype.setupTabDragAndDrop = function (fileTab, fe) {

    var fs = this;
    var vm = fs.vm;

    var dragoverNest = 0;

    function resetDragoverNest() {
        dragoverNest = 0;
        fileTab.classList.remove('cb-drag-over');
    }

    function handleDragStart(event) {

        if (vm.isDisabledDND()) return;

        var file = fe.file;
        var opts = {};

        vm.addLinkToHTML(opts);

        opts.url = file.toURL(false, { activated: true, launch: false });

        var format = 'rich';
        if (event.shiftKey || event.altKey || event.ctrlKey) format = 'link';

        opts.format = format;

        var shareableData = file.toShareableData(opts);

        var dt = event.dataTransfer;
        dt.effectAllowed = 'copyMove';
        vm.setDataTransferFromShareableData(dt, shareableData);

        fileTab.setAttribute('data-cb-dragstart', '');
        fileTab.classList.add('cb-dragging');
    }

    function handleDragEnd(event) {
        if (vm.isDisabledDND()) return;
        fileTab.classList.remove('cb-dragging');
    }

    function handleDragEnter(event) {
        if (vm.isDisabledDND()) return;
        if (dragoverNest++ === 0) {
            fileTab.classList.add('cb-drag-over');
        }
    }

    function handleDragLeave(event) {
        if (vm.isDisabledDND()) return;
        if (--dragoverNest === 0) {
            resetDragoverNest();
        }
    }

    function handleDragOver(event) {
        if (vm.isDisabledDND()) return;
        fileTab.removeAttribute('data-cb-dragstart');
        if (event.dataTransfer.getData('text/codeboot-file-name') !== '') {
            return false;
        }
    }

    function handleDrop(event) {
        if (vm.isDisabledDND()) return;
        resetDragoverNest();
        event.stopPropagation(); // stops the browser from redirecting.
        var dt = event.dataTransfer;
        var sourceFilename = event.dataTransfer.getData('text/codeboot-file-name');
        if (sourceFilename === '') {
            if (vm.editable) {
                vm.handleDrop(event);
            }
        } else {
            event.preventDefault();
            var parent = fileTab.parentNode;
            var index = Array.prototype.indexOf.call(parent.childNodes, fileTab);
            var fem = fs.fem;
            fem.moveTabs(fem.indexOfFilename(sourceFilename), index);
        }
        return false;
    }

    if (fe) {
        fileTab.addEventListener('dragstart', handleDragStart);
        fileTab.addEventListener('dragend', handleDragEnd);
    }

    fileTab.addEventListener('dragenter', handleDragEnter);
    fileTab.addEventListener('dragleave', handleDragLeave);
    fileTab.addEventListener('dragover', handleDragOver);
    fileTab.addEventListener('drop', handleDrop);
};

CodeBootVM.prototype.clipboardItemFromShareableData = function (shareableData) {

    var vm = this;

    if (window.ClipboardItem === undefined) return null;

    var dict = {};

    console.log('shareable data:');

    for (var i=0; i<shareableData.length; i++) {
        var type = shareableData[i][0];
        var data = shareableData[i][1];
        if (type === 'text/plain' || type === 'text/html') {
            console.log('>>>>> data[' + i + ']: ' + type + '=|' + data + '|');
            dict[type] = new Blob([data], { type: type });
        }
    }

    return new ClipboardItem(dict);
};

CodeBootVM.prototype.setDataTransferFromShareableData = function (dataTransfer, shareableData) {

    var vm = this;

    console.log('shareable data:');

    for (var i=0; i<shareableData.length; i++) {
        var type = shareableData[i][0];
        var data = shareableData[i][1];
        console.log('>>>>> data[' + i + ']: ' + type + '=|' + data + '|');
        dataTransfer.setData(type, data);
    }
};

CodeBootFileSystem.prototype.clear = function () {

    var fs = this;

    fs.builtins = {};
    fs.files = Object.create(fs.builtins);
    fs._loadBuiltins();
};

CodeBootFileSystem.prototype._loadBuiltins = function () {

    var fs = this;

    for (var filename in BUILTIN_FILES) {
        var f = new CodeBootFile(fs, filename, BUILTIN_FILES[filename]);
        fs.builtins[filename] = f;
    };
};

CodeBootFileSystem.prototype._asFilename = function (fileOrFilename) {

    var fs = this;

    if (typeof fileOrFilename === 'string') return fileOrFilename;
    return fileOrFilename.filename;
};

CodeBootFileSystem.prototype._asFile = function (fileOrFilename) {

    var fs = this;

    if (typeof fileOrFilename !== 'string') return fileOrFilename;
    return fs.getByName(fileOrFilename);
};

CodeBootFileSystem.prototype.isBuiltin = function (fileOrFilename) {

    var fs = this;
    var filename = fs._asFilename(fileOrFilename);

    return Object.prototype.hasOwnProperty.call(fs.builtins, filename);
};

CodeBootFileSystem.prototype.isHiddenFilename = function (fileOrFilename) {

    var fs = this;
    var filename = fs._asFilename(fileOrFilename);

    return filename.match(/(^\.|\/\.)/);
};

CodeBootFileSystem.prototype.isValidFilename = function (fileOrFilename, allowHidden) {

    var fs = this;
    var filename = fs._asFilename(fileOrFilename);

    if (allowHidden === undefined) {
        allowHidden = fs.vm.priviledged;
    }

    return filename.match(/^[-_./a-zA-Z0-9]*$/) && // letter, digits, etc
        !filename.match(/(^$|\/\/|\/$)/) && // not empty, or // or terminal /
        (allowHidden || !fs.isHiddenFilename(filename));
};

CodeBootFileSystem.prototype.addFile = function (f) {

    var fs = this;

    fs.files[f.filename] = f;
};

CodeBootFileSystem.prototype.hasFile = function (fileOrFilename) {

    var fs = this;
    var filename = fs._asFilename(fileOrFilename);

    return Object.prototype.hasOwnProperty.call(fs.files, filename) ||
           Object.prototype.hasOwnProperty.call(fs.builtins, filename);
};

CodeBootFileSystem.prototype.generateUniqueFilename = function (filename, suffix) {

    var fs = this;
    var vm = fs.vm;
    var candidateName;

    if (!filename) {
        filename = vm.translateToCurrentLang('untitled') + vm.lang.getExts()[0];
    }

    if (!fs.hasFile(filename)) return filename;

    var afterDir = filename.lastIndexOf('/')+1;
    var dir = filename.slice(0, afterDir);
    var base = filename.slice(afterDir);
    var dot = base.lastIndexOf('.');
    var ext = '';

    if (dot >= 0) {
        ext = base.slice(dot);
        base = base.slice(0, dot);
    }

    var root = dir + base;

    if (suffix) {
        root += suffix;
        candidateName = root + ext;
        if (!fs.hasFile(candidateName)) return candidateName;
    }

    var index = 2; // start numbering at 2

    while (true) {
        candidateName = root + '-' + index + ext;
        if (!fs.hasFile(candidateName)) break;
        index++;
    }

    return candidateName;
};

CodeBootFileSystem.prototype.getByName = function (filename) {

    var fs = this;

    if (!fs.hasFile(filename)) {
        throw 'File not found: "' + filename + '"';
    }

    var file = fs.files[filename];

    if (!Object.prototype.hasOwnProperty.call(fs.files, filename)) {
        // This is a builtin file, make an editable copy
        file = file.clone();
        fs.files[filename] = file;
    }

    return file;
};

CodeBootFileSystem.prototype.deleteFile = function (fileOrFilename, avoidRebuild) {

    var fs = this;
    var filename = fs._asFilename(fileOrFilename);

    if (Object.prototype.hasOwnProperty.call(fs.files, filename)) {
        var file = fs.files[filename];
        file.fe.disable();
        delete fs.files[filename];
        if (!avoidRebuild) {
            fs.rebuildFileMenu();
        }
        return true;
    }

    return false;
};

CodeBootFileSystem.prototype.renameFile = function (fileOrFilename, newFilename, avoidRebuild) {

    var fs = this;

    if (fs.hasFile(newFilename)) {
        //TODO: translate?
        throw 'File already exists: "' + newFilename + '"';
    }

    var file = fs._asFile(fileOrFilename);

    delete fs.files[file.filename];
    file.filename = newFilename;
    fs.addFile(file);
    file.fe.setFilename(newFilename);
    if (!avoidRebuild) {
        fs.rebuildFileMenu();
    }
};

CodeBootFileSystem.prototype.getContent = function (fileOrFilename) {

    var fs = this;
    var file = fs._asFile(fileOrFilename);

    return file.getContent();
};

CodeBootFileSystem.prototype.getTextEditor = function (fileOrFilename) {

    var fs = this;

    return fs._asFile(fileOrFilename).fe.textEditor;
};

CodeBootFileSystem.prototype.setContent = function (fileOrFilename, content) {

    var fs = this;
    var file = fs._asFile(fileOrFilename);

    file.setContent(content);
};

CodeBootFileSystem.prototype.each = function (callback, selector) {

    var fs = this;

    if (!selector) selector = function (f) { return true; };

    for (var filename in fs.files) {

        if (!fs.hasFile(filename)) continue; // Prune Object method name

        var file = fs.getByName(filename);
        if (selector(file)) {
            callback(file);
        }
    }
};

CodeBootFileSystem.prototype.forEachFileEditor = function (callback) {

    var fs = this;

    fs.fem.fileEditors.forEach(callback);
};

CodeBootFileSystem.prototype.serialize = function () {

    var fs = this;
    var json = [];
    var isUserFile = function (file) {
        return Object.prototype.hasOwnProperty.call(fs.files, file.filename);
    };

    fs.each(function (file) {
        json.push(file.serialize());
    },
    isUserFile);

    return json;
};

CodeBootFileSystem.prototype.restore = function (json) {

    var fs = this;

    fs.clear();

    for (var i = 0; i < json.length; i++) {
        var fileProps = json[i];
        var filename = fileProps.filename;
        var content = fileProps.content;
        if (typeof filename === 'string' && typeof content === 'string') {
            var file = new CodeBootFile(fs, filename, content, fileProps);
            fs.addFile(file);
        }
    }
};

CodeBootVM.prototype.copyAppToClipboard = function (type, format) {

    var vm = this;

    var shareableData = vm.stateToShareableData(type, format);

    vm.shareableDataToClipboard(shareableData);
};

CodeBootVM.prototype.stateToShareableData = function (type, format, opts) {

    var vm = this;
    var fs = vm.fs;

    var linkNameTemplate = 'Image of {0}';

    switch (type) {
    case 'step':
        linkNameTemplate = 'Single-step {0}';
        break;
    case 'animate':
        linkNameTemplate = 'Animate {0}';
        break;
    case 'eval':
    case 'execute':
        type = 'execute';
        linkNameTemplate = 'Execute {0}';
        break;
    case 'webapp':
        type = 'webapp';
        linkNameTemplate = '{0}';
        break;
    case 'stop':
    case 'bundle':
        type = 'bundle';
        linkNameTemplate = 'Bundle {0}';
        break;
    default:
        type = 'image';
    }

    var fe = fs.fem.currentlyActivated();
    var launch = vm.findLaunch();
    var asFile = fe !== null && !vm.hasAttribute('data-cb-focus-repl');

    opts = (opts === undefined) ? {} : Object.assign({}, opts);

    opts.url = vm.toURL(type, opts);
    opts.format = format;

    var f;

    if (asFile) {
        if (type === 'image' && launch === null) {
            f = new TFormat('Image', []);
        } else {
            f = new TFormat(linkNameTemplate, [vm.appName(launch)]);
        }
    } else {
        f = new TFormat(linkNameTemplate, ['console']);
    }

    opts.linkHTML = vm.translateTFormat(vm.getLanguage(), f);

    if (asFile) {
        return fe.file.toShareableData(opts);
    } else {
        return vm.replToShareableData(opts);
    }
};

CodeBootVM.prototype.setupElemDragAndDrop = function (elem) {

    var vm = this;

    function handleDragStart(event) {

        var type = 'image';

        if (elem.parentNode.classList.contains('cb-exec-btn-step')) {
            type = 'step';
        } else if (elem.parentNode.classList.contains('cb-exec-btn-eval')) {
            type = 'eval';
        } else if (elem.parentNode.classList.contains('cb-exec-btn-stop')) {
            type = 'stop';
        }

        var format = 'rich';
        if (event.shiftKey || event.altKey || event.ctrlKey) format = 'link';

        var shareableData = vm.stateToShareableData(type, format);

        var dt = event.dataTransfer;
        dt.effectAllowed = 'copyMove';
        vm.setDataTransferFromShareableData(dt, shareableData);

        elem.setAttribute('data-cb-dragstart', '');
        elem.classList.add('cb-dragging');
    }

    function handleDragEnd(event) {
        elem.classList.remove('cb-dragging');
        //console.log('dragend');
    }

    function handleDragEnter(event) {
        elem.removeAttribute('data-cb-dragstart');
        //console.log('dragenter');
    }

    function handleDragLeave(event) {
        elem.removeAttribute('data-cb-dragstart');
        //console.log('dragleave');
    }

    function handleDragOver(event) {
        elem.removeAttribute('data-cb-dragstart');
        //console.log('dragover');
    }

    elem.addEventListener('dragstart', handleDragStart);
    elem.addEventListener('dragend', handleDragEnd);

    elem.addEventListener('dragenter', handleDragEnter);
    elem.addEventListener('dragleave', handleDragLeave);
    elem.addEventListener('dragover', handleDragOver);
};

CodeBootFileSystem.prototype.initFileMenu = function () {

    var fs = this;
    var vm = fs.vm;

    //TODO: fix
    vm.forEachElem('.cb-navbar-controls div[draggable="true"]', function (elem) {
        vm.setupElemDragAndDrop(elem);
    });

    fs.rebuildFileMenu();
};

CodeBootFileSystem.prototype.rebuildFileMenu = function () {

    var fs = this;
    var vm = fs.vm;

    fs.vm.forEachElem('.cb-menu-file', function (menu_elem) {

        menu_elem.removeAttribute('data-cb-cloud-status');

        //menu_elem.setAttribute('data-cb-cloud-status', 'dirty');

        var elem = menu_elem.querySelector(':scope > .cb-file-selection');

        elem.innerHTML = ''; // remove children

        var newFile =
            fs.addMenuItem(elem,
                           'cb-file-new dropdown-item',
                           vm.polyglotHTML('New file'));

        newFile.addEventListener('click', function (event) {
            fs.newFile().fe.rename();
        });

        var divider = null;

        fs.each(function (file) {
            if (!fs.isHiddenFilename(file) || fs.vm.priviledged) {
                if (!divider) {
                    divider = fs.addMenuDivider(elem);
                }
                fs.addFileToMenu(elem, file);
            }
        });

        fs.addMenuItem(elem,
                       'cb-file-attention dropdown-header',
                       vm.polyglotHTML('Non-persistent file system'),
                       newFile);

        if (divider) {

            var before = null;

            fs.addMenuDivider(elem);

            var closeOpened =
                fs.addMenuItem(elem,
                               'cb-fs-close-opened dropdown-item',
                               vm.polyglotHTML('Close all opened files'),
                               before);

            closeOpened.addEventListener('click', function (event) {
                fs.removeFileEditors();
            });

            var downloadOpened =
                fs.addMenuItem(elem,
                               'cb-fs-download-opened dropdown-item',
                               vm.polyglotHTML('Download all opened files'),
                               before);

            downloadOpened.addEventListener('click', function (event) {
                fs.downloadAsZip(true);
            });

            var downloadAll =
                fs.addMenuItem(elem,
                               'cb-fs-download-all dropdown-item',
                               vm.polyglotHTML('Download all files'),
                               before);

            downloadAll.addEventListener('click', function (event) {
                fs.downloadAsZip(false);
            });

            fs.addMenuDivider(elem);

            var reset_item;
            var reset_warning;

            if (vm.isPersistent()) {
                reset_item = 'Reset file system';
                reset_warning = 'Reset file system? This will remove all your local files (in this browser). This cannot be undone.';
            } else {
                reset_item = 'Clear file menu';
                reset_warning = 'Clear file menu? Because the file system is non-persistent this has no effect on any local files saved in this browser.';
            }

            var reset =
                fs.addMenuItem(elem,
                               'cb-fs-reset dropdown-item',
                               vm.polyglotHTML(reset_item),
                               before);

            reset.addEventListener('click', function (event) {
                vm.confirmHTML(vm.polyglotHTML(reset_warning),
                               function (yes) {
                                   if (yes) {
                                       vm.stop(null);
                                       vm.fs.init();
                                       vm.repl.focus();
                                   }
                               },
                               true); // Cancel is default
            });

            if (vm.isPersistent()) {

                var nonpersistent =
                    fs.addMenuItem(elem,
                                   'cb-fs-nonpersistent dropdown-item',
                                   vm.polyglotHTML('Change file system to non-persistent'),
                                   before);

                nonpersistent.addEventListener('click', function (event) {
                    vm.confirmHTML(vm.polyglotHTML('Change file system to non-persistent? This will stop saving your changes to local files (in this browser).'),
                                   function (yes) {
                                       if (yes) {
                                           vm.setPersistent(false);
                                           vm.fs.rebuildFileMenu();
                                       }
                                   },
                                   true); // Cancel is default
                });
            }
        }

        fs.rebuildFileMenuHook(elem, divider);
    });
};

CodeBootFileSystem.prototype.rebuildFileMenuHook = function (elem, divider) {
};

CodeBootFileSystem.prototype.addMenuItem = function (elem, cls, html, before) {

    var item = document.createElement('div');
    item.className = cls;

    var span = document.createElement('span');
    span.innerHTML = html;

    item.appendChild(span);

    if (!before) before = null;

    elem.insertBefore(item, before);

    return item;
};

CodeBootFileSystem.prototype.addMenuDivider = function (elem, before) {

    var item = document.createElement('div');
    item.className = 'dropdown-divider';

    if (!before) before = null;

    elem.insertBefore(item, before);

    return item;
};

CodeBootFileSystem.prototype.addButton = function (buttons, title, html, onClick) {

    var button = document.createElement('button');

    button.className = 'close';

    if (title && !CodeBoot.prototype.hasTouchInterface()) {
        button.setAttribute('data-toggle', 'tooltip');
        button.setAttribute('data-delay', '750');
        button.setAttribute('data-animation', 'false');
        button.setAttribute('data-placement', 'bottom');
        button.setAttribute('data-title', title);
    }

    button.innerHTML = html;

    button.addEventListener('click', onClick);

    buttons.appendChild(button);

    return button;
};

CodeBootFileSystem.prototype.addFileToMenu = function (elem, file) {

    var fs = this;
    var vm = fs.vm;
    var filename = file.filename;

    //console.log('filename='+filename);
    function dismissMenu() {
        $(elem).find($('[data-toggle="tooltip"]')).tooltip('hide');
        elem.classList.remove('show');
    }

    var item = fs.addMenuItem(elem,
                              'dropdown-item',
                              CodeBoot.prototype.escapeHTML(filename));

    item.setAttribute('data-cb-filename', filename);
    item.setAttribute('data-cb-cloud-status', 'clean');

    item.addEventListener('click', function (event) {
        event.stopPropagation();
        dismissMenu();
        file.fe.edit();
    });

    var status = document.createElement('span');

    status.classList.add('cb-file-status');

//    status.innerHTML = vm.getImage('cloud-clean') + vm.getImage('cloud-dirty');

    item.appendChild(status);

    var nodes = elem.childNodes;

    for (var i=2; i<nodes.length; i++) {
        var e = nodes[i];
        if (filename < e.getAttribute('data-cb-filename')) {
            elem.insertBefore(item, e);
            return;
        }
    }

    $(elem).find($('[data-toggle="tooltip"]')).tooltip();
};

CodeBootFileSystem.prototype.downloadAsZip = function (openedFilesOnly) {

    var fs = this;
    var vm = fs.vm;

    var files = [];
    var stamp = vm.cb.dateToTimeStamp(new Date());

    function addFile(file) {
        var filename = file.filename;
        var content = file.getContent();
        files.push({ filename: filename, content: content });
    }

    if (openedFilesOnly) {
        fs.forEachFileEditor(function (fe) {
            addFile(fe.file);
        });
        var name = stamp + '-' + vm.appName(vm.findLaunch());
        vm.downloadFilesAsZip(files, name);
    } else {
        fs.each(addFile);
        var name = stamp + '-codeBoot';
        vm.downloadFilesAsZip(files, name);
    }
};

CodeBootFile.prototype.delete = function () {

    var file = this;
    var fs = file.fs;
    var vm = fs.vm;
    var filename = file.filename;

    vm.confirmHTML(vm.polyglotHTML('Delete file "{}"? This cannot be undone.',
                                   [filename]),
                   function (yes) {
                       if (yes) {
                           fs.deleteFile(filename);
                       }
                   },
                  true); // Cancel is default
};

CodeBootFile.prototype.download = function () {

    var file = this;
    var filename = file.filename;
    var content = file.getContent();

    download(content, filename, 'text/plain');
/*deprecated
    var elem = document.createElement('a');
    elem.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(content));
    elem.setAttribute('download', filename);

    elem.style.display = 'none';
    document.body.appendChild(elem);

    elem.click();

    document.body.removeChild(elem);
*/
};

CodeBootFile.prototype.email = function () {
    var file = this;
    var filename = file.filename;
    var content = file.getContent();
    var url = ''; //editor_URL(content, filename) + '\n\n\n';
    var subject = encodeURIComponent(filename);
    var body = encodeURIComponent(url+content);
    var href = 'mailto:?subject=' + subject + '&body=' + body;
    var w = window.open(href, '_blank');
    if (w) w.close();
};

CodeBootVM.prototype.copyTextToClipboard = function (text) {

    var vm = this;

    navigator.clipboard.writeText(text).then(function () {
        //console.log('copyTextToClipboard used writeText successfully');
    }, function () {
        //console.log('copyTextToClipboard using execCommand fallback');
        var textArea = document.createElement('textarea');
        textArea.value = text;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
    });
};

CodeBootFile.prototype.copyToClipboard = function (opts) {

    var file = this;
    var fs = file.fs;
    var vm = fs.vm;

    vm.shareableDataToClipboard(file.toShareableData(opts));
};

CodeBootVM.prototype.shareableDataToClipboard = function (shareableData) {

    var vm = this;

    var text = null;

    var ci = vm.clipboardItemFromShareableData(shareableData);

    if (ci) {
        console.log('clipboard.write');
        console.log(shareableData);
        navigator.clipboard.write([ci]);
    } else {

        // as a fallback use execCommand('copy')

        console.log('execCommand(\'copy\')');
        console.log(shareableData);

        function handler(event) {
            vm.setDataTransferFromShareableData(event.clipboardData, shareableData);
            event.preventDefault();
        }

        document.addEventListener('copy', handler);
        document.execCommand('copy');
        document.removeEventListener('copy', handler);
    }
};

CodeBootVM.prototype.addLinkToHTML = function (opts) {

    var vm = this;

    function embedHTML(opts) {
        var HTML = opts.HTML;
        if (opts.url && opts.linkHTML) {
            var link = '<a href="' + opts.url + '"';
            if (opts.fontSize) {
                link += ' style="font-size:' + opts.fontSize + ';"';
            }
            HTML = link + opts.linkHTML + '</a>'+ '<br>\n' + HTML;
        }
        return HTML;
    }

    opts.embedHTML = embedHTML;
};

CodeBootFile.prototype.toShareableData = function (opts) {

    var file = this;
    var fe = file.fe;
    var content = file.getContent();
    var result = [];
    var html = null;

    opts = (opts === undefined) ? {} : Object.assign({}, opts);

    if (fe.isEnabled()) {
        if (fe.currentEditorView === 'spreadsheet') {
            result.push(['text/csv', content]);
        } else {

            var filename = file.filename;

            var metaInfo = CodeBoot.prototype.encodeMetaInfo('file', CodeBoot.prototype.typeMetaInfo) +
                CodeBoot.prototype.encodeMetaInfo(filename, CodeBoot.prototype.filenameMetaInfo);

            if (opts.metaInfo) {
                opts.metaInfo += metaInfo;
            } else {
                opts.metaInfo = metaInfo;
            }

            if (opts.format === 'link-rich') {

                var embedHTML = opts.embedHTML;

                opts.embedHTML = function (opts) {
                    if (embedHTML === undefined) {
                        return opts.HTML;
                    } else {
                        if (opts.linkHTML === undefined) {
                            opts.linkHTML = CodeBoot.prototype.escapeHTML(filename);
                        }
                        return embedHTML(opts);
                    }
                };
            }

            html = fe.textEditor.toHTML(opts);

            if (opts.format === 'rich' || opts.format === 'link-rich') {
                result.push(['text/html', html]);
            }
        }
    }

    if (html !== null && (opts.format === 'html' || opts.format === 'link-html')) {
        result.push(['text/plain', html]);
    } else if (opts.url && opts.format === 'link') {
        result.push(['text/plain', opts.url]);
    } else {
        result.push(['text/plain', content]);
    }

    result.push(['text/codeboot-file-name', file.filename]);

    if (opts.url) {
        result.push(['text/uri-list', opts.url]);
    }

    return result;
};

CodeBootVM.prototype.replToShareableData = function (opts) {

    var vm = this;

    var result = [];

    opts = (opts === undefined) ? {} : Object.assign({}, opts);

    var source = vm.replGetInput();

    opts.endLine = vm.replInputPos().line;

    if (vm.isRunning()) {
        source = vm.lastSource;
    } else {
        opts.endLine += (source.length === 0 ? 0 : 1);
    }

    var metaInfo = CodeBoot.prototype.encodeMetaInfo('input', CodeBoot.prototype.typeMetaInfo) +
        CodeBoot.prototype.encodeMetaInfo(source, CodeBoot.prototype.inputMetaInfo);

    if (opts.metaInfo) {
        opts.metaInfo += metaInfo;
    } else {
        opts.metaInfo = metaInfo;
    }

    var sourceLines = source.split('\n');
    var content = [vm.lang.getPrompt()+sourceLines[0]].concat(sourceLines.slice(1).map(function (line) { return vm.lang.getPromptCont()+line; })).join('\n');

    var html = CodeBootVM.prototype.cmToHTML(vm.repl, opts);

    result.push(['text/html', html]);

    if (html !== null && (opts.format === 'html' || opts.format === 'link-html')) {
        result.push(['text/plain', html]);
    } else if (opts.url && opts.format === 'link') {
        result.push(['text/plain', opts.url]);
    } else {
        result.push(['text/plain', content]);
    }

    result.push(['text/codeboot-input', source]);

    if (opts.url) {
        result.push(['text/uri-list', opts.url]);
    }

    return result;
};

CodeBootVM.prototype.cmToHTML = function (cm, opts) {

    var vm = this;

    opts = (opts === undefined) ? {} : Object.assign({}, opts);

    if (opts.fontSize === undefined) opts.fontSize = '18px';
    if (opts.fontFamily === undefined) opts.fontFamily = '&quot;Consolas&quot;,&quot;Monaco&quot;,&quot;Courier New&quot;,monospace';
    if (opts.whiteSpace === undefined) opts.whiteSpace = 'pre';
    if (opts.startLine === undefined) opts.startLine = 0;
    if (opts.endLine === undefined) opts.endLine = cm.lineCount();

    var relevantStyles = ['text-transform', 'color', 'font-weight'];
    var attrs = '';

    // work around google docs bug that turns black into green
    var quasiBlack = 'rgb(1, 1, 1)';

    var style = 'color:' + quasiBlack + ';';

    if (opts.fontSize || opts.fontFamily || opts.whiteSpace) {
        if (opts.fontSize) {
            style += 'font-size:' + opts.fontSize + ';';
        }
        if (opts.fontFamily) {
            style += 'font-family:' + opts.fontFamily + ';';
        }
        if (opts.whiteSpace) {
            style += 'white-space:' + opts.whiteSpace + ';';
        }
    }

    var lineBreak = '<br>';
    var HTML = '';
    var prevLineBreak = '';
    var fontWeight = '';

    function getGutterText(line) {
        var info = cm.lineInfo(line);
        var gutter = '';
        var gms = info.gutterMarkers;
        if (gms) {
            var gutterElem = gms['cb-repl-cm-gutter'];
            if (gutterElem) {
                gutter = CodeBoot.prototype.unescapeHTML(gutterElem.innerHTML);
            }
        }
        return gutter;
    }

    function gutterHTML(text, pad) {
        return CodeBoot.prototype.escapeHTML(text.padEnd(pad, ' ')).replace(/ /g, '&nbsp;');
    }

    var maxGutterLength = 0;

    for (var i=opts.startLine; i<opts.endLine; i++) {
        maxGutterLength = Math.max(maxGutterLength, getGutterText(i).length);
    }

    for (var i=opts.startLine; i<opts.endLine; i++) {

        var lineHTML = gutterHTML(getGutterText(i), maxGutterLength);
        var lineTokens = cm.getLineTokens(i, true);

        for (var j=0; j<lineTokens.length; j++) {
            var t = lineTokens[j];
            var token = CodeBoot.prototype.escapeHTML(t.string);
            var tokenType = t.type;
            var css = '';
            if (tokenType) {

                var elem = document.querySelector('.cm-'+tokenType);
                if (elem) {
                    var compStyle = window.getComputedStyle(elem, null);

                    relevantStyles.forEach(function (prop) {
                        var s = prop + ':' + compStyle.getPropertyValue(prop) + ';';
                        if (s !== fontWeight && s !== 'text-transform:none;') {
                            if (prop === 'font-weight') {
                                if (fontWeight === '') {
                                    fontWeight = s;
                                    style += s;
                                } else {
                                    css += s;
                                }
                            } else if (prop === 'color') {
                                if (s === 'color:rgb(0, 0, 0);') {
                                    s = 'color:' + quasiBlack + ';';
                                }
                                css += s;
                            } else {
                                css += s;
                            }
                        }
                    });

                }
            }
            if (css !== '') {
                lineHTML += '<span style="' + css + '">';
            } else {
                lineHTML += '<span>';
            }
            lineHTML += token.replace(/ /g, '&nbsp;') + '</span>';
        }

        var info = cm.lineInfo(i);
        var widgets = info.widgets;
        if (widgets) {
            lineHTML += widgets.map(function (w) {
                return lineBreak + gutterHTML('', maxGutterLength) + w.node.outerHTML;
            }).join('');
        }

        if (lineHTML !== '' || i < opts.endLine-1) {
            HTML += prevLineBreak + lineHTML;
            prevLineBreak = lineBreak;
        }
    }

//    attrs += ' lang="' + vm.getLanguage() + '"';

    if (style !== '') {
        style = 'style="' + style + '"';
        attrs += ' ' + style;
    }

    var link = '';

    if (opts.url) {

        link = '<span data-cb-link><a href="' + opts.url + '"';
        if (opts.fontSize) {
            link += ' style="font-size:' + opts.fontSize + ';"';
        }
        link += '>';
        if (opts.linkHTML) {
            link += '<span data-cb-text>' + opts.linkHTML + lineBreak + lineBreak + '</span>';
        }
        if (opts.format === 'html' || opts.format === 'link-html') {
            link += '<span data-cb-image style="display:none">' + vm.getImage('clone') + '</span>';
        }
        link += '</a></span>';
    }

    if (opts.metaInfo) {
        HTML = '<div' + opts.metaInfo + '>' + link +
            '<div' + attrs + '>' + '<code>' + HTML + '</code></div></div>';
    } else {
        HTML = link + '<code' + attrs + '>' + HTML + '</code>';
    }

    var embedHTML = opts.embedHTML;

    if (embedHTML === undefined) {
        return HTML;
    } else {
        opts.HTML = HTML;
        return embedHTML(opts);
    }
};

CodeBootFileSystem.prototype.openFile = function (fileOrFilename) {

    var fs = this;
    var file = fs._asFile(fileOrFilename);

    file.fe.edit();
};

CodeBootFileSystem.prototype.showFile = function (fileOrFilename, show) {

    var fs = this;
    var filename = fs._asFilename(fileOrFilename);

    if (show === undefined) {
        show = true;
    }

    if (show) {
        fs.openFileExistingOrNew(filename);
    } else {
        if (fs.hasFile(filename)) {
            var file = fs._asFile(filename);
            var fe = file.fe;
            if (fe.isEnabled()) {
                fs.fem.remove(fe);
            }
        }
    }
};

CodeBootFileSystem.prototype.focusFile = function (fileOrFilename) {
    var fs = this;
    
    var filename = fs._asFilename(fileOrFilename);

    if (fs.hasFile(filename)) fs._asFile(filename).fe.focus();
}

CodeBootFileSystem.prototype.createFileNoClobber = function (filename, content,  opts, suffix, cont) {

    var fs = this;
    var vm = fs.vm;

    if (!suffix) {
        suffix = vm.translateToCurrentLang('-old');
    }

    function replaceFile(file) {
        file.setContent(content);
        cont(file);
    }

    function renameFile(newFilename) {
        file.fs.renameFile(file, newFilename);
        newFile();
    }

    function newFile() {
        cont(fs.createFile(filename, content, opts));
    }

    if (filename && fs.hasFile(filename)) {

        var file = fs._asFile(filename);
        var oldContent = file.getContent();

        if (content === oldContent) {
            cont(file);
            return;
        }

        var uniqueFilename = fs.generateUniqueFilename(filename, suffix);
        vm.askHTML(vm.polyglotHTML('The file "{0}" is about to be replaced with a different content. Do you want to replace it and lose the current content, or rename it to a file named "{1}"?', [filename, uniqueFilename]),
                   ['Cancel', 'Replace file', '!Rename file'],
                   function (answer) {
                       if (answer === 'Replace file') {
                           replaceFile(file);
                       } else if (answer === 'Rename file') {
                           renameFile(uniqueFilename);
                       } else {
                           cont(null);
                       }
                   });
    } else {
        newFile();
    }
};

CodeBootFileSystem.prototype.createFile = function (filename, content, opts) {

    var fs = this;

    if (!filename) {
        filename = fs.generateUniqueFilename();
    }

    var file = new CodeBootFile(fs, filename, content, opts);

    fs.addFile(file);
    fs.rebuildFileMenu();

    return file;
};

CodeBootFileSystem.prototype.newFile = function (filename, content, opts) {

    var fs = this;

    var file = fs.createFile(filename, content, opts);

    file.fe.edit();

    return file;
};

CodeBootFileSystem.prototype.openFileExistingOrNew = function (filename) {

    var fs = this;

    if (fs.hasFile(filename)) {
        fs.openFile(filename);
        return true;
    } else {
        fs.newFile(filename);
        return false;
    }
};

CodeBootFileSystem.prototype.removeFileEditors = function (filter) {

    var fs = this;

    fs.fem.removeFileEditors(filter);
};

CodeBootFileSystem.prototype.pathIsURL = function (path) {
    return /^[a-zA-Z][-+.a-zA-Z0-9]*:\/\//.test(path);
};

CodeBootFileSystem.prototype.pathIsHTTP = function (path) {
    return /^[hH][tT][tT][pP][sS]?:\/\//.test(path);
};

CodeBootFileSystem.prototype.pathIsWS = function (path) {
    return /^[wW][sS][sS]?:\/\//.test(path);
};

