function endsWith(str, suffix) {
    return str.indexOf(suffix, str.length - suffix.length) !== -1;
}

CodeBootVM.prototype.getStorageId = function () {

    var vm = this;

    return vm.storageId;
};

CodeBootVM.prototype.getStorage = function () {

    var vm = this;

    try {
        var storage = localStorage[vm.getStorageId()];
        if (storage)
            return storage;
        else
            return null;
    } catch (e) {
        return null;
    }
};

CodeBootVM.prototype.setStorage = function (value) {

    var vm = this;

    try {
        localStorage[vm.getStorageId()] = value;
    } catch (e) {
    }
};

CodeBootVM.prototype.clearStorage = function () {

    var vm = this;

    localStorage.removeItem(vm.getStorageId());
};

CodeBootVM.prototype.clearAllStorage = function () {

    var vm = this;

    localStorage.clear();
};

CodeBootVM.prototype.saveSession = function () {

    var vm = this;

    if (vm.isPersistent()) {

        var state = vm.serializeState();

        vm.setStorage(JSON.stringify(state));
    }
};

CodeBootVM.prototype.loadSession = function () {

    var vm = this;

    if (vm.isPersistent()) {

        vm.setPersistent(false, true); // in case restoreState fails

        var state = vm.getStorage();

        if (!state || vm.restoreState(JSON.parse(state))) {
            vm.setPersistent(true, true);
            vm.fs.rebuildFileMenu();
        }
    }
};

CodeBootVM.prototype.serializeState = function () {

    var vm = this;

    var state = {
        repl: {
            history: undefined
        },
        lang: vm.lang.getId() + '-' + vm.level,
        showLineNumbers: vm.showLineNumbers,
        largeFont: vm.largeFont,
        animationSpeed: vm.animationSpeed,
        language: vm.getAttribute('lang'),
        options: vm.options
    };

    state.repl.history = vm.repl.cb.hm.serializeState();

    state.files = vm.fs.serialize();
    state.openEditors = [];
    vm.fs.forEachFileEditor(function (fe) {
        state.openEditors.push(fe.file.filename);
    });
    state.activeEditor = null;
    if (vm.fs.fem.activated >= 0) {
        state.activeEditor = vm.fs.fem.fileEditors[vm.fs.fem.activated].file.filename;
    }
    state.launchEditor = vm.findLaunch(true);
    return state;
};

function cb_internal_attempt(operation) {
    try {
        operation();
        return false;
    } catch (e) {
        console.log(e);
        return true;
    }
}

CodeBootVM.prototype.restoreState = function (state) {

    var vm = this;

    if (state === undefined) return;

    var failed = false;

    if (state.options) {
        cb.options = state.options;
    }

    failed = cb_internal_attempt(function () {
        vm.repl.cb.hm.restoreState(state.repl.history);
    }) || failed;

    failed = cb_internal_attempt(function () {
        vm.setLang(state.lang || vm.cb.defaultLang);
        vm.setLangUI();
    }) || failed;

    failed = cb_internal_attempt(function () {
        vm.setDevMode(!!state.devMode);
    }) || failed;

    failed = cb_internal_attempt(function () {
        vm.setShowLineNumbers(!!state.showLineNumbers);
    }) || failed;

    failed = cb_internal_attempt(function () {
        vm.setLargeFont(!!state.largeFont);
    }) || failed;

    failed = cb_internal_attempt(function () {
        vm.setAnimationSpeed(state.animationSpeed);
    }) || failed;

    failed = cb_internal_attempt(function () {
        var language = state.language;
        if (language) {
            vm.setLanguage(language);
        }
    }) || failed;

    if (state.files) {
        failed = cb_internal_attempt(function () {
            vm.fs.restore(state.files);
            vm.fs.rebuildFileMenu();
        }) || failed;
    }

    if (state.openEditors) {
        failed = cb_internal_attempt(function () {
            state.openEditors.forEach(function (filename) {
                vm.fs.openFile(filename);
            });
        }) || failed;
    }

    if (state.activeEditor) {
        failed = cb_internal_attempt(function () {
            var file = vm.fs._asFile(state.activeEditor);
            file.fe.activate();
        }) || failed;
    }

    if (state.launchEditor) {
        failed = cb_internal_attempt(function () {
            var file = vm.fs._asFile(state.launchEditor);
            file.fe.toggleLaunch();
        }) || failed;
    }

    //TODO: add translation?
    if (failed) {
        vm.reportError('Failed to restore state');
    }

    return !failed;
};

function cb_tutorial() {
    if (cb.inTutorial) return;
    cb.inTutorial = true;
    cb_tutorial1();
}

function cb_tutorial_setREPLExpression() {
    cb.stop();
    cb.query('replay=1+2*3');
    cb.handle_query();
    cb.focusREPL();
}

function cb_tutorial1() {
    $('#cb-repl').popover({
	animation: true,
	placement: 'bottom',
	trigger: 'manual',
	title: 'Console',
	content:
            '<p>This is the Console.  After the prompt, enter the JavaScript code you wish to execute.</p> ' +
	    '<p><a class="btn btn-primary" onclick="cb_tutorial_setREPLExpression();">Show me</a> ' +
	    '<a class="btn btn-primary" onclick="cb_tutorial2();">Next</a></p>',
	html: true,
    });

    $('#cb-repl').popover('show');
    cb.focusREPL();
}

function cb_tutorial2() {
    $('#cb-repl').popover('destroy');
    $('#play-button').popover({
	animation: true,
	placement: 'bottom',
	trigger: 'manual',
	title: 'Play button',
	content:
            '<p>Use this button to evaluate the code entered at the Console, or simply press the Enter key.</p>' +
	    '<p><a class="btn btn-primary" onclick="cb_tutorial_setREPLExpression();' + "setTimeout(function () { $('#play-button').click(); }, 100);" + '">Show me</a> ' +
	    '<a class="btn btn-primary" onclick="cb_tutorial3();">Next</a></p>',
	html: true,
    });

    $('#play-button').popover('show');
    cb.focusREPL();
}

function cb_tutorial3() {
    $('#play-button').popover('destroy');
    $('#step-button').popover({
	animation: true,
	placement: 'bottom',
	trigger: 'manual',
	title: 'Step button',
	content:
            '<p>Use this button to execute one step of the code.</p>' +
	    '<p><a class="btn btn-primary" onclick="cb_tutorial_setREPLExpression();' + "setTimeout(function () { $('#step-button').click(); }, 100); cb_tutorial4();" + '">Show me</a>  ' +
	    '<a class="btn btn-primary" onclick="cb_tutorial_end();">Done</a></p>',
	html: true,
    });

    $('#step-button').popover('show');
    cb.focusREPL();
}

function cb_tutorial4() {
    $('#step-button').popover('destroy');
    $('#step-button').popover({
	animation: false,
	placement: 'bottom',
	trigger: 'manual',
	title: 'Step button',
	content:
            '<p>Press the button again to execute the next step. Repeat until the code is fully evaluated, or press the Play button.</p>' +
	    '<p><a class="btn btn-primary" onclick="cb_tutorial_end();">Done</a></p>',
	html: true,
    });

    $('#step-button').popover('show');
    cb.focusREPL();
}

function cb_tutorial_end() {
    $('#step-button').popover('destroy');
    cb.focusREPL();
    cb.inTutorial = false;
}

function runtime_chart(rte, params) {
    var custom_temporal_types = ["unix_timestamp", "timestamp"];
    var normal_types = ["temporal", "quantitative", "ordinal", "nominal"]

    function normalize_axis_type(type) {
        if (custom_temporal_types.includes(type)) {
            return "temporal";
        } else if (normal_types.includes(type)) {
            return type;
        } else {
            return "quantitative";
        };
    };

    function get_data_min_max(data, key) {
        var min = +data[0][key];
        var max = +data[0][key];

        data.forEach(datum => {
            var val = +datum[key];
            if (val < min) {
                min = val;
            } else if (val > max) {
                max = val;
            }
        });

        return [min, max];
    };

    function get_time_format(data, key) {
        var formatting_units = ["%Y-", "%m-%d ", "%H:%M:", "%S.", "%L "] // space after %L is required

        function make_format(hi, lo) {
            return formatting_units.slice(hi, lo + 1).join('').slice(0, -1)
        }

        function all_same(fn, ...dates) {
            for (let i = 1; i < dates.length; i++) {
                if (fn(dates[i]) !== fn(dates[i-1])) {
                    return false;
                };
            };
            return true;
        };

        function in_same_year(...dates) {
            return all_same(d => d.getFullYear(), ...dates);
        }

        function in_same_day(...dates) {
            return all_same(d => d.getDate(), ...dates);
        }

        function in_same_minute(...dates) {
            return all_same(d => d.getMinutes(), ...dates);
        }
        
        // range of the data determines the smallest significant unit (ex: range across monthes does not require seconds)
        const [min, max] = get_data_min_max(data, key);
        const range = max - min;

        // distance to today represents the highest required unit (ex: no need to display year if in same year)
        const current_time = new Date(Date.now());
        const max_time = new Date(max);
        const min_time = new Date(min);

        let hi;
        let lo;
        
        if (range < 10 * 1000) { // less than 10 seconds, display ms
            lo = 4;
        } else if (range < 60 * 1000) { // less than 1 minute, display seconds
            lo = 3;
        } else if (range < 3 * 24 * 60 * 60 * 1000) { // less than 3 days, display hours
            lo = 2
        } else if (range < 5 * 365 * 24 * 60 * 60 * 1000) { // less than 5 years, display date
            lo = 1;
        } else { // more than that, only display years
            lo = 0;
        };

        if (in_same_year(current_time, max_time, min_time)) {
            if (in_same_day(current_time, max_time, min_time)) {
                hi = in_same_minute(current_time, max_time, min_time) ? 3 : 2;
            } else {
                hi = 1;
            };
        } else {
            hi = 0; // otherwise, show full date
        };

        hi = Math.min(hi, lo);
        return make_format(hi, lo);
    };

    var vm = rte.vm;

    var { data,
          mark,
          width, height,
          x_type, y_type,
          x_axis, y_axis,
          legend,
          opacity,
          y_columns,
          x_column, } = params;

    var col_names = data[0];

    var width = width || "container";
    var height = height || "container";
    var x_type = x_type || "quantitative";
    var y_type = y_type || "quantitative";
    var legend = legend || "";
    var opacity = !opacity ? 1 : opacity;
    var x_column = x_column || 0;
    var displayed_columns = y_columns ? y_columns.filter(x => col_names.includes(x)): col_names.slice(1);
    var x_axis = x_axis == null ? col_names[x_column] : x_axis;
    var y_axis = y_axis == null ? displayed_columns[0] : y_axis;

    var has_legend = displayed_columns.length > 1 || legend;

    // Temporary solution for our custom temporal types, should be generalized once there is more
    // than 'unix_timestamp' and 'timestamp'
    var format_x_datum = x_type === "unix_timestamp" ? x => x * 1000 : x => x;
    var format_y_datum = y_type === "unix_timestamp" ? y => y * 1000 : y => y;

    function format_datum(x, y, group) {
        let formatted_x = format_x_datum(x);
        let formatted_y = format_y_datum(y);
        formatted_y = formatted_y === "" ? undefined : formatted_y; // do not display empty data
        return { "x": formatted_x, "y": formatted_y, "group": group }
    };

    var data_as_objects = [];
    for (let row_index = 1; row_index < data.length; row_index++) {
        let row = data[row_index];
        for (let i = 0; i < row.length; i++) {
            if (i !== x_column) {
                data_as_objects.push(format_datum(row[x_column], row[i], col_names[i]));
            };
        };
    };

    var dataset = {
        "name": "chart_data",
        "values": data_as_objects,
    };

    // https://vega.github.io/vega/docs/schemes/
    var color_scheme = col_names.length < 10 ? "tableau10" : "tableau20";

    var encoding = {
        "x": { "field": "x",
               "type": normalize_axis_type(x_type),
               "axis": { "title": x_axis,
                         "labelOverlap": "parity", },
               "scale": { "nice": false },
             },
        "y": { "field": "y",
               "type": normalize_axis_type(y_type),
               "axis": { "title": y_axis } },
        "color": { "field": "group",
                   "scale": { "scheme": color_scheme },
                   "axis": { "title": legend },
                   "sort": col_names,
                },
        "opacity": { "value": opacity },
    };

    var transform = [];

    // Remove the legend if not required
    if (!has_legend) {
        delete encoding['color'];
    }

    // x axis order for nominal data
    if (x_type === 'nominal') {
        encoding['x']['sort'] = [new Set(data_as_objects.map(o => o.x))];
    }

    // Set axis to HH:MM:SS format
    if (custom_temporal_types.includes(x_type)) {
        encoding['x']['axis']["format"] = get_time_format(data_as_objects, "x");
        encoding['x']['axis']['labelAngle'] = -90;
    }

    if (custom_temporal_types.includes(y_type)) {
        encoding['y']['axis']["format"] = get_time_format(data_as_objects, "y");
    }

    // Do not overlap bars in bar mode for data that are not on a continuuum
    if (mark === "bar" && (x_type == "nominal" || x_type == "ordinal")) {
        encoding["xOffset"] = { "field": "group" }
    }

    if (y_columns) {
        transform.push({
            "filter": { "field": "group", "oneOf": y_columns }
        });
    };

    var query = {
        "width": width,
        "height": height,
        "data": dataset,
        "mark": mark,
        "encoding": encoding,
        "transform": transform,
    };

    vm.withElem('.cb-chart-window', function (chart) {

        // Finalize previous vega chart to prevent memory leak
        if (vm.chartVegaViewFinalizer) {
            vm.chartVegaViewFinalizer();
            // delete the finalizer since it's a closure with reference to the view
            delete vm.chartVegaViewFinalizer;
        };

        vegaEmbed(chart, query)
            .then(function (result) {
                // Store a reference to the Vega finalizer in the chart element
                vm.chartVegaViewFinalizer = result.finalize;
                chart.classList.remove('vega-embed'); // causes bug on Safari
            });

        vm.setPlaygroundToShow('chart');
    });
};

